"""TRAIN section — launch / monitor / history. Ports ui/components/sections/train/*.

LAUNCH: config form + start/stop + live RUN.STATUS panel.
MONITOR: running-session picker + LIVE/STALLED/NO FEED chip + RunDetail (polled).
HISTORY: runs (pick model+stage → RunDetail) | compare (table + overlay charts).

Backed by train.sv.jac (start/stop/status/sessions) + runs.sv.jac (get_run/compare).
Polling uses manual `useEffect` + setInterval so the interval is re-established when
its deps change (avoids stale-closure reads); cross-tick stall tracking lives in an
effect-local dict (mutated by reference, never via React state).

(There used to be a ⟳ UPDATE APP button here. It had no backend at all — it
showed a "restarting · reloads in ~20s" banner and then just reloaded the page,
plus leaked two uncleaned setTimeouts that fired from an unmounted section. A
control that lies about restarting the app is worse than no control, so it is
gone; add it back only alongside a real /system/update endpoint.)
"""

import from react { useEffect }
sv import from ...train { start_training, stop_training, get_status, list_sessions }
sv import from ...backends { list_backends }
sv import from ...runs { get_run, compare_runs }
import from ..shared.SubTabs { SubTabs }
import from ..shared.Field { Field, TextInput, Segmented }
import from ..shared.StatusGlyph { StatusGlyph }
import from ..shared.LogView { LogView }
import from ..shared.StatTile { StatTile }
import from ..shared.MonoChart { MonoChart }
import from ..shared.MultiLineChart { MultiLineChart }
import from ...lib.chartkit { chartColor }

glob TABS: list[str] = ["LAUNCH", "MONITOR", "HISTORY"];
# Chart accents are chartkit palette SLOTS, not hex — the old literals were
# dark-theme-only and washed out on the cream light background.
glob CC: dict = {"loss": 0, "lr": 1, "tps": 5, "acc": 4};
glob MODE_DESC: dict = {
    "sft": "supervised finetune · teaches the model to write Jac",
    "dpo": "preference tuning · pushes outputs toward idiomatic Jac"
};

def _availBackends(backends: list, mode: str) -> list {
    out: list = [];
    for b in backends {
        for m in list(b["methods"]) {
            if str(m) == mode {
                out.append(b);
                break;
            }
        }
    }
    return out;
}

def _backendDesc(backends: list, backendId: str) -> str {
    for b in backends {
        if str(b["id"]) == backendId { return str(b["description"]); }
    }
    return "";
}

def _optKeysFor(backends: list, backendId: str, mode: str) -> list {
    for b in backends {
        if str(b["id"]) != backendId { continue; }
        # NOT isinstance(): a JSON-derived plain object has constructor.name
        # "Object", so `isinstance(x, dict)` lowers to _tagSubclass("Object",
        # "dict") == False and this always returned []. `k in obj` is the
        # idiom that actually works on server dicts (see doStart's `k in opts`).
        if "method_details" not in b { return []; }
        details = b["method_details"];
        if details is None or mode not in details { return []; }
        md = details[mode];
        if md is None or "env_keys" not in md { return []; }
        raw = md["env_keys"];
        if raw is None { return []; }
        return [str(k) for k in raw];
    }
    return [];
}

# ---------------------------------------------------------------------------
# numeric/format helpers (no `any` locals in the arithmetic)
# ---------------------------------------------------------------------------

def _fix(v: any, n: int) -> str {
    return str(v.toFixed(n));
}

def _idiomPctNum(s: any) -> any {
    hsv = bool(s["has"]);
    runs = int(str(s["runs"]));
    idio = int(str(s["idiomatic"]));
    if hsv and runs > 0 { return round(idio * 100 / runs); }
    return None;
}

def _idiomPct(s: any) -> str {
    v = _idiomPctNum(s);
    if v is None { return "·"; }
    return str(v) + "%";
}

def _idiomSub(s: any, fallback: str) -> str {
    if not bool(s["has"]) { return fallback; }
    return f"{s['idiomatic']}/{s['runs']} idiomatic · sim {s['avg_sim']} · {s['total']} tasks";
}

# ---------------------------------------------------------------------------
# RunDetail — 4 headline tiles + 2 holdout tiles + 4 charts + log tail
# ---------------------------------------------------------------------------

def:pub RunDetail(metrics: any, live: bool) -> JsxElement {
    train: list = list(metrics["train"]);
    val: list = list(metrics["val"]);
    lr: list = list(metrics["lr"]);
    tps: list = list(metrics["tps"]);
    curve: list = list(metrics["curve"]);
    lastTrain: any = train[len(train) - 1] if len(train) > 0 else None;
    lastVal: any = val[len(val) - 1] if len(val) > 0 else None;
    lastTps: any = tps[len(tps) - 1] if len(tps) > 0 else None;
    lastAcc: any = curve[len(curve) - 1] if len(curve) > 0 else None;
    fi: any = metrics["func_idiom"];
    gi: any = metrics["graph_idiom"];

    return <>
        <div className="grid grid-cols-4 gap-3">
            <StatTile label="ACCURACY · TEST-PASS%" value={(str(lastAcc["y"]) + "%") if lastAcc is not None else "·"} sub="cross-compiled holdout" dim={False} />
            <StatTile label="LAST.ITER" value={str(metrics["last_iter"])} sub="" dim={False} />
            <StatTile label="FINAL.LOSS" value={_fix(lastTrain["y"], 3) if lastTrain is not None else "·"} sub={("val " + _fix(lastVal["y"], 3)) if lastVal is not None else ""} dim={False} />
            <StatTile label="TOK/S" value={_fix(lastTps["y"], 0) if lastTps is not None else "·"} sub="" dim={False} />
        </div>

        <div className="grid grid-cols-2 gap-3">
            <StatTile label="FUNCTION HOLDOUT · IDIOMATIC" value={_idiomPct(fi)} sub={_idiomSub(fi, "no function-holdout eval")} dim={False} />
            <StatTile label="GRAPH HOLDOUT · IDIOMATIC" value={_idiomPct(gi)} sub={_idiomSub(gi, "no graph-holdout eval")} dim={False} />
        </div>

        <div className="grid grid-cols-2 gap-4">
            <MonoChart title="LOSS · train + val" data={train} secondary={val} live={live} accent={chartColor(int(str(CC["loss"])))} expY={False} />
            <MonoChart title="LEARNING.RATE" data={lr} secondary={[]} live={False} accent={chartColor(int(str(CC["lr"])))} expY={True} />
            <MonoChart title="TOKENS/SEC" data={tps} secondary={[]} live={False} accent={chartColor(int(str(CC["tps"])))} expY={False} />
            <MonoChart title="ACCURACY · TEST-PASS%" data={curve} secondary={[]} live={live} accent={chartColor(int(str(CC["acc"])))} expY={False} />
        </div>

        <LogView text={str(metrics["log_tail"])} maxH="12rem" />
    </>;
}

# ---------------------------------------------------------------------------
# compare table helpers
# ---------------------------------------------------------------------------

def _hMetrics(h: any) -> dict {
    return {
        "fp": float(str(h["final_pass"])),
        "ll": float(str(h["last_loss"])),
        "li": int(str(h["last_iter"])),
        "fpct": _idiomPctNum(h["func_idiom"]),
        "gpct": _idiomPctNum(h["graph_idiom"]),
        "fhas": bool(h["func_idiom"]["has"]),
        "ghas": bool(h["graph_idiom"]["has"]),
        "fsim": str(h["func_idiom"]["avg_sim"]),
        "gsim": str(h["graph_idiom"]["avg_sim"])
    };
}

def _cmpRow(label: str, cells: list, nums: list, best: str) -> JsxElement {
    valid: list = [n for n in nums if n is not None];
    leader: any = None;
    if len(valid) > 1 {
        leader = max(valid) if best == "max" else min(valid);
    }
    return <tr key={label} className="border-t border-border">
        <td className="py-1.5 pr-4 text-muted-foreground">{label}</td>
        {for (i, c) in enumerate(cells) {
            <td key={str(i)} className={"py-1.5 px-4 text-right " + (
                "text-foreground font-semibold" if (leader is not None and nums[i] is not None and nums[i] == leader) else "text-muted-foreground"
            )}>{c}</td>
        }}
    </tr>;
}

def _compareTable(headline: list) -> JsxElement {
    hm: list = [_hMetrics(h) for h in headline];
    names: list = [str(h["name"]) for h in headline];
    accCells: list = [f"{m['fp']}%" for m in hm];
    accNums: list = [m["fp"] for m in hm];
    lossCells: list = [str(m["ll"]) for m in hm];
    lossNums: list = [m["ll"] for m in hm];
    iterCells: list = [str(m["li"]) for m in hm];
    iterNums: list = [m["li"] for m in hm];
    fpctCells: list = ["·" if m["fpct"] is None else f"{m['fpct']}%" for m in hm];
    fpctNums: list = [m["fpct"] for m in hm];
    fsimCells: list = [m["fsim"] if m["fhas"] else "·" for m in hm];
    gpctCells: list = ["·" if m["gpct"] is None else f"{m['gpct']}%" for m in hm];
    gpctNums: list = [m["gpct"] for m in hm];
    gsimCells: list = [m["gsim"] if m["ghas"] else "·" for m in hm];
    nullNums: list = [None for m in hm];

    return <div className="relative exp-panel p-3 pt-5 overflow-x-auto">
        <span className="micro-label absolute -top-2 left-3 bg-background px-2">COMPARISON</span>
        <table className="w-full border-collapse font-mono text-xs">
            <thead>
                <tr>
                    <th className="micro-label py-2 pr-4 text-left font-normal">METRIC</th>
                    {for (i, nm) in enumerate(names) {
                        <th key={nm} className="py-2 px-4 text-right font-normal" style={{"color": chartColor(i)}}>{str(nm).upper()}</th>
                    }}
                </tr>
            </thead>
            <tbody>
                {_cmpRow({"label": "ACCURACY · TEST-PASS%", "cells": accCells, "nums": accNums, "best": "max"})}
                {_cmpRow({"label": "FINAL LOSS", "cells": lossCells, "nums": lossNums, "best": "min"})}
                {_cmpRow({"label": "ITERATIONS", "cells": iterCells, "nums": iterNums, "best": "max"})}
                {_cmpRow({"label": "FUNCTION HOLDOUT · IDIOMATIC%", "cells": fpctCells, "nums": fpctNums, "best": "max"})}
                {_cmpRow({"label": "FUNCTION HOLDOUT · SIM", "cells": fsimCells, "nums": nullNums, "best": "min"})}
                {_cmpRow({"label": "GRAPH HOLDOUT · IDIOMATIC%", "cells": gpctCells, "nums": gpctNums, "best": "max"})}
                {_cmpRow({"label": "GRAPH HOLDOUT · SIM", "cells": gsimCells, "nums": nullNums, "best": "min"})}
            </tbody>
        </table>
    </div>;
}

# ---------------------------------------------------------------------------
# TRAIN
# ---------------------------------------------------------------------------

def:pub Train(active: bool) -> JsxElement {
    has tab: str = "launch";
    has sessions: list = [];
    has formModelId: str = "Qwen/Qwen3-Coder-30B-A3B-Instruct";
    has formName: str = "qwen";
    has formMode: str = "sft",
        formBackend: str = "mlx_local",
        backends: list = [],
        opts: dict = {
        "EVAL_EVERY": "60", "SUBSET": "50", "DRY_ITERS": "30", "SKIP_DRY": "0",
        "DPO_ITERS": "200", "DPO_LR": "1e-6", "DPO_BETA": "0.1"
    };
    has job: any = None;
    has error: str = "";
    has selName: str = "";
    has selMode: str = "";
    has metrics: any = None;
    has feed: str = "nofeed";
    has stalledFor: int = 0;
    has compare: any = None;
    has compareMode: str = "sft";
    has historyView: str = "runs";
    has histName: str = "";
    has histMode: str = "sft";
    has historyMetrics: any = None;

    # ---- async fetchers (set state only; logic params passed explicitly) ----
    async def _loadBackends() -> None {
        try {
            r = await list_backends();
            backends = list(r["backends"]);
            formBackend = str(r["default"]);
        } except Exception {}
    }
    async def _pollSessions() -> None {
        try {
            r = await list_sessions();
            sessions = list(r["sessions"]);
        } except Exception {}
    }
    async def _pollStatus(nm: str, md: str) -> None {
        try {
            j = await get_status(name=nm, mode=md);
            job = j;
            error = "";
        } except Exception {
            error = "fetch error";
        }
    }
    async def _pollMetrics(nm: str, md: str, tracker: dict) -> None {
        try {
            m = await get_run(name=nm, mode=md);
            metrics = m;
            if not bool(m["found"]) or not bool(m["running"]) {
                feed = "nofeed";
                return;
            }
            li = int(str(m["last_iter"]));
            if li > int(str(tracker["iter"])) {
                tracker["iter"] = li;
                tracker["same"] = 0;
                feed = "live";
                stalledFor = 0;
            } else {
                sm = int(str(tracker["same"])) + 1;
                tracker["same"] = sm;
                if sm >= 12 {
                    feed = "stalled";
                    stalledFor = int(sm * 5 / 2);
                }
            }
        } except Exception {}
    }
    async def _fetchCompare(cm: str) -> None {
        try {
            r = await compare_runs(mode=cm);
            compare = r;
        } except Exception {}
    }
    async def _fetchHistMetrics(nm: str, md: str) -> None {
        try {
            m = await get_run(name=nm, mode=md);
            historyMetrics = m;
        } except Exception {}
    }

    # ---- polling effects ----
    useEffect(lambda {
        if active { _loadBackends(); }
    }, [active]);

    useEffect(lambda {
        avail = _availBackends(backends, formMode);
        if len(avail) == 0 { return; }
        ok = False;
        for b in avail {
            if str(b["id"]) == formBackend { ok = True; break; }
        }
        if not ok { formBackend = str(avail[0]["id"]); }
    }, [formMode, backends]);

    useEffect(lambda {
        iv: any = None;
        if active {
            _pollSessions();
            iv = setInterval(lambda { _pollSessions(); }, 5000);
        }
        return lambda { if iv is not None { clearInterval(float(str(iv))); } };
    }, [active]);

    useEffect(lambda {
        running: list = [s for s in sessions if str(s["status"]) == "running"];
        if selName != "" {
            still: list = [s for s in running if str(s["name"]) == selName and str(s["mode"]) == selMode];
            if len(still) == 0 { selName = ""; selMode = ""; }
        }
        if selName == "" and len(running) > 0 {
            selName = str(running[0]["name"]);
            selMode = str(running[0]["mode"]);
        }
    }, [sessions]);

    useEffect(lambda {
        iv: any = None;
        if active and tab == "launch" and formName != "" {
            nm = formName;
            md = formMode;
            _pollStatus(nm, md);
            iv = setInterval(lambda { _pollStatus(nm, md); }, 2500);
        }
        return lambda { if iv is not None { clearInterval(float(str(iv))); } };
    }, [active, tab, formName, formMode]);

    useEffect(lambda {
        iv: any = None;
        if active and tab == "monitor" and selName != "" {
            nm = selName;
            md = selMode;
            tracker: dict = {"iter": -1, "same": 0};
            cb = lambda { _pollMetrics(nm, md, tracker); };
            cb();
            iv = setInterval(cb, 2500);
        }
        return lambda { if iv is not None { clearInterval(float(str(iv))); } };
    }, [active, tab, selName, selMode]);

    useEffect(lambda {
        if active and tab == "history" { _fetchCompare(compareMode); }
    }, [active, tab, compareMode]);

    useEffect(lambda {
        if active and tab == "history" and historyView == "runs" and histName != "" {
            _fetchHistMetrics(histName, histMode);
        }
    }, [active, tab, historyView, histName, histMode]);

    useEffect(lambda {
        if active and tab == "history" and historyView == "runs" and histName == "" {
            cands: list = [s for s in sessions if str(s["mode"]) == compareMode and str(s["status"]) != "running"];
            if len(cands) > 0 {
                histName = str(cands[0]["name"]);
                histMode = str(cands[0]["mode"]);
            }
        }
    }, [active, tab, historyView, sessions, compareMode]);

    # ---- actions ----
    def onTab(t: str) -> None { tab = t.lower(); }
    def updateForm(key: str, value: str) -> None {
        if key == "modelId" { formModelId = value; }
        elif key == "name" { formName = value; }
        elif key == "mode" { formMode = value; }
    }
    def updateOpt(key: str, value: str) -> None {
        opts = {**opts, key: value};
    }
    def pickSession(nm: str, md: str) -> None {
        selName = nm; selMode = md; feed = "nofeed"; stalledFor = 0;
    }
    def pickHistory(nm: str, md: str) -> None {
        histName = nm; histMode = md; historyMetrics = None;
    }
    async def doStart() -> None {
        keys = _optKeysFor(backends, formBackend, formMode);
        filtered: dict = {};
        for k in keys {
            if k in opts { filtered[k] = str(opts[k]); }
        }
        mid = formModelId if formMode == "sft" else "";
        try {
            j = await start_training(formName, formMode, mid, filtered, formBackend);
            job = j;
            error = "";
        } except Exception {
            error = "start failed";
        }
    }
    async def doStop() -> None {
        try {
            j = await stop_training(name=formName, mode=formMode);
            job = j;
        } except Exception {
            error = "stop failed";
        }
    }
    # ---- LAUNCH tab ----
    def _launch() -> JsxElement {
        isRunning = job is not None and str(job["status"]) == "running";
        optKeys = _optKeysFor(backends, formBackend, formMode);
        availBackends = _availBackends(backends, formMode);
        btn = "exp-btn ";
        return <div className="flex items-start gap-4 p-4 pt-5">
            <div className="relative flex min-w-0 flex-1 flex-col gap-3 exp-panel p-4 pt-5">
                <span className="micro-label absolute -top-2 left-3 bg-background px-2">LAUNCH.CONFIG</span>

                {len(availBackends) > 0 and <Field label="BACKEND">
                    <div className="flex flex-wrap gap-1">
                        {for b in availBackends {
                            bid = str(b["id"]);
                            <button
                                key={bid}
                                onClick={lambda (e: MouseEvent) { formBackend = bid; }}
                                className={"exp-chip !text-xs " + (
                                    "exp-chip-active" if formBackend == bid
                                    else ""
                                )}
                            >
                                {str(b["label"])}
                            </button>
                        }}
                    </div>
                    {formBackend and <p className="stat-line text-muted-foreground/80">{_backendDesc(backends, formBackend)}</p>}
                </Field>}

                {formMode == "sft" and <Field label="BASE MODEL (HF ID)">
                    <TextInput value={formModelId} onSet={lambda (v: str) { updateForm("modelId", v); }} placeholder="org/model" mono={True} />
                </Field>}

                <Field label="SHORT NAME">
                    <TextInput value={formName} onSet={lambda (v: str) { updateForm("name", v); }} placeholder="qwen" mono={True} />
                </Field>

                <Field label="MODE">
                    <Segmented options={["sft", "dpo"]} value={formMode} onSet={lambda (v: str) { updateForm("mode", v); }} />
                </Field>

                {for key in optKeys {
                    <Field key={key} label={key}>
                        <TextInput value={str(opts[key]) if key in opts else ""} onSet={lambda (v: str) { updateOpt(key, v); }} placeholder={key} mono={True} />
                    </Field>
                }}

                <p className="stat-line mt-1 text-muted-foreground">heavy workload · one training at a time, runs detached</p>

                <div className="mt-2 flex gap-2">
                    <button onClick={lambda (e: MouseEvent) { doStart(); }} disabled={isRunning} className={btn + "text-foreground"}>▶ START {formMode.upper()}</button>
                    <button onClick={lambda (e: MouseEvent) { doStop(); }} disabled={not isRunning} className={btn + "text-muted-foreground"}>■ STOP</button>
                </div>

                {error and <p className="stat-line mt-1 text-muted-foreground">{error}</p>}
            </div>

            <div className="relative flex min-w-0 flex-1 flex-col gap-3 exp-panel p-4 pt-5">
                <span className="micro-label absolute -top-2 left-3 bg-background px-2">RUN.STATUS</span>

                <div className="flex flex-wrap items-center gap-3">
                    <StatusGlyph status={str(job["status"]) if job is not None else "idle"} showLabel={True} />
                </div>

                {job is not None and <div className="flex flex-col gap-1">
                    {int(str(job["pid"])) > 0 and <span className="font-mono text-[11px] text-muted-foreground">PID {str(job["pid"])}</span>}
                    {str(job["started"]) and <span className="font-mono text-[11px] text-muted-foreground">STARTED {str(job["started"])}</span>}
                    {int(str(job["last_iter"])) > 0 and <span className="font-mono text-[11px] text-muted-foreground">LAST ITER {str(job["last_iter"])}</span>}
                </div>}

                <LogView text={str(job["log_tail"]) if job is not None else ""} maxH="24rem" />
            </div>
        </div>;
    }

    # ---- MONITOR tab ----
    def _feedChip() -> JsxElement {
        if feed == "live" {
            return <span className="font-mono text-[10px] tracking-widest text-accent">⦿ LIVE</span>;
        }
        if feed == "stalled" {
            return <span className="font-mono text-[10px] tracking-widest text-muted-foreground">⦿ STALLED {str(stalledFor)}s</span>;
        }
        return <span className="font-mono text-[10px] tracking-widest text-muted-foreground/80">○ NO FEED</span>;
    }

    def _monitor() -> JsxElement {
        running: list = [s for s in sessions if str(s["status"]) == "running"];
        if len(running) == 0 {
            return <div className="flex h-full flex-1 flex-col items-center justify-center gap-1 p-4">
                <span className="micro-label">NO LIVE RUNS</span>
                <span className="stat-line text-muted-foreground/80">launch from the LAUNCH tab · finished runs live in HISTORY</span>
            </div>;
        }
        found = metrics is not None and bool(metrics["found"]);
        return <div className="flex h-full min-h-0 flex-col gap-4 overflow-y-auto p-4">
            <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="flex flex-wrap items-center gap-1">
                    {for s in running {
                        <button
                            key={str(s["name"]) + "|" + str(s["mode"])}
                            onClick={lambda (e: MouseEvent) { pickSession(str(s["name"]), str(s["mode"])); }}
                            className={"exp-hoverable rounded-lg border px-3 py-1 font-mono text-[10px] tracking-widest transition-colors " + (
                                "border-accent bg-accent/15 text-foreground" if (selName == str(s["name"]) and selMode == str(s["mode"]))
                                else "border-input text-muted-foreground hover:text-foreground/80"
                            )}
                        >
                            {str(s["label"]) if "label" in s else (str(s["name"]) + "·" + str(s["mode"]))}
                        </button>
                    }}
                </div>
                {_feedChip()}
            </div>

            {not found and <div className="flex flex-1 items-center justify-center"><span className="micro-label">NO RUN DATA</span></div>}
            {found and <RunDetail metrics={metrics} live={feed == "live"} />}
        </div>;
    }

    # ---- HISTORY tab ----
    # Stage accent from the theme palette (was `border-[#b89ce8]` / `text-[#7aa2f7]`
    # arbitrary-value Tailwind — dark-only, unreadable on the cream light page).
    def _stageColor(mode: str) -> str {
        return chartColor(4) if mode == "dpo" else chartColor(1);
    }

    def _hasRun(pool: list, nm: str, md: str) -> bool {
        for s in pool {
            if str(s["name"]) == nm and str(s["mode"]) == md { return True; }
        }
        return False;
    }

    def _historyRuns(pastSessions: list) -> JsxElement {
        if len(pastSessions) == 0 {
            return <div className="flex flex-1 items-center justify-center"><span className="micro-label">NO FINISHED RUNS</span></div>;
        }
        mdls: list[str] = [];
        for s in pastSessions {
            nm = str(s["name"]);
            if nm not in mdls { mdls.append(nm); }
        }
        selModel = histName;
        selModeH = histMode if histMode != "" else "sft";
        return <>
            <div className="flex flex-wrap items-end gap-x-8 gap-y-3">
                <div className="flex flex-col gap-1.5">
                    <span className="micro-label">MODEL</span>
                    <div className="flex gap-2">
                        {for name in mdls {
                            <button
                                key={name}
                                onClick={lambda (e: MouseEvent) { pickHistory(name, selModeH); }}
                                className={"exp-hoverable rounded-lg border px-4 py-1.5 font-mono text-xs transition-colors " + (
                                    "border-accent bg-accent/15 text-foreground" if selModel == name
                                    else "border-border text-muted-foreground hover:border-ring hover:text-foreground"
                                )}
                            >
                                {name}
                            </button>
                        }}
                    </div>
                </div>

                <div className="flex flex-col gap-1.5">
                    <span className="micro-label">STAGE</span>
                    <div className="flex gap-2">
                        {for mode in ["sft", "dpo"] {
                            <button
                                key={mode}
                                disabled={not (_hasRun(pastSessions, selModel, mode) if selModel != "" else True)}
                                onClick={lambda (e: MouseEvent) { pickHistory(selModel if selModel != "" else mdls[0], mode); }}
                                className={"exp-hoverable rounded-lg border px-4 py-1.5 font-mono text-xs uppercase tracking-widest transition-colors disabled:opacity-30 " + (
                                    "bg-secondary" if selModeH == mode
                                    else "border-border text-muted-foreground hover:border-ring hover:text-foreground"
                                )}
                                style={{"borderColor": _stageColor(mode), "color": _stageColor(mode)} if selModeH == mode else {}}
                            >
                                {mode}
                            </button>
                        }}
                    </div>
                </div>

                <span className="stat-line pb-1.5 text-muted-foreground/80">{str(MODE_DESC[selModeH]) if selModeH in MODE_DESC else ""}</span>
            </div>

            {histName == "" and <div className="flex flex-1 items-center justify-center"><span className="micro-label">SELECT A MODEL ABOVE</span></div>}
            {histName != "" and not (historyMetrics is not None and bool(historyMetrics["found"])) and <div className="flex flex-1 items-center justify-center"><span className="micro-label">NO RUN DATA</span></div>}
            {histName != "" and historyMetrics is not None and bool(historyMetrics["found"]) and <RunDetail metrics={historyMetrics} live={False} />}
        </>;
    }

    def _historyCompare() -> JsxElement {
        hasData = compare is not None and len(list(compare["names"])) > 0;
        return <>
            <div className="flex items-center gap-3">
                <Segmented options={["sft", "dpo"]} value={compareMode} onSet={lambda (v: str) { compareMode = v; }} />
            </div>
            {not hasData and <div className="flex flex-1 items-center justify-center"><span className="micro-label">NO PAST RUNS</span></div>}
            {hasData and <>
                {_compareTable({"headline": list(compare["headline"])})}
                <div className="grid grid-cols-1 gap-4">
                    <MultiLineChart title="ACCURACY · TEST-PASS%" rows={list(compare["curve"])} names={list(compare["names"])} />
                    <MultiLineChart title="LOSS.TRAIN" rows={list(compare["train"])} names={list(compare["names"])} />
                    <MultiLineChart title="LOSS.VAL" rows={list(compare["val"])} names={list(compare["names"])} />
                </div>
            </>}
        </>;
    }

    def _history() -> JsxElement {
        pastSessions: list = [s for s in sessions if str(s["status"]) != "running"];
        return <div className="flex h-full min-h-0 flex-col gap-4 overflow-y-auto p-4">
            <div className="flex flex-wrap items-center gap-3">
                <Segmented options={["runs", "compare"]} value={historyView} onSet={lambda (v: str) { historyView = v; }} />
                <span className="stat-line text-muted-foreground/80">{"inspect one finished run in detail" if historyView == "runs" else "overlay every run of one stage"}</span>
            </div>
            {historyView == "runs" and _historyRuns({"pastSessions": pastSessions})}
            {historyView == "compare" and _historyCompare()}
        </div>;
    }

    return <div className="flex h-full min-w-0 flex-1 flex-col">
        <div className="section-header flex items-center justify-between border-b border-border px-4 py-2.5">
            <SubTabs tabs={TABS} active={tab.upper()} onTab={onTab} />
            <div className="flex items-center gap-2">
                <span className="micro-label text-muted-foreground/80">TRAIN.CTL</span>
            </div>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto">
            {tab == "launch" and _launch()}
            {tab == "monitor" and _monitor()}
            {tab == "history" and _history()}
        </div>
    </div>;
}

"""Task walkers: the kanban board API."""

import from models {
    Project,
    Member,
    Task,
    TaskView,
    TaskPage,
    TaskTotals,
    ProjectTally,
    MemberTally,
    WorkflowStep,
    AssignedTo,
    ForProject,
    OnProject,
    TaskLinks,
    task_links,
    hydrate_views,
    views_from,
    resolve,
    on_attached,
    owned
}
import from walkers.util {
    now_iso,
    today_iso,
    shift_day,
    page_bounds,
    clean_tags,
    done_cutoff,
    is_older,
    order_working
}
import from walkers.log { record_task_event, sync_task_links }
import from constants { STATUSES, KIND_STATUS, ACTIVE_STATUSES }


# The legacy status a step stands for. Every move writes both, so the rest of
# the app keeps reading `status` and never has to know about steps.
def status_for_step(holder: Root, step_id: str) -> str {
    step = resolve(step_id);
    if not isinstance(step, WorkflowStep) or not owned(holder, step) {
        return "";
    }
    return KIND_STATUS[step.kind] if step.kind in KIND_STATUS else "In Progress";
}

# The step's owner role is a hand-off: moving a task onto a step hands it to
# whoever holds that role ON THE TASK'S PROJECT. Returns that one member, or
# an empty list when the answer is ambiguous: no owner, "anyone", no project,
# or any count of holders but one. The caller leaves assignees alone on empty.
def handoff_target(holder: Root, task: Task, step: WorkflowStep) -> list[Member] {
    role = step.owner.strip() if step.owner else "";
    if not role or role == "anyone" {
        return [];
    }
    owning = [task->:ForProject:->];
    if not owning {
        return [];
    }
    project = owning[0];
    holders: list[Member] = [];
    for m in [holder-->[?:Member]] {
        if m.active and role in m.roles and [edge m->:OnProject:->project] {
            holders.append(m);
        }
    }
    if len(holders) != 1 {
        return [];
    }
    return holders;
}

# -------------------------------------------------------------------- tasks

# How well a title matches a search: exact, then prefix, then anywhere. Lower
# ranks first, so the assistant's exact title always lands on page 1.
def title_rank(title: str, needle: str) -> int {
    low = title.lower().strip();
    if low == needle {
        return 0;
    }
    if low.startswith(needle) {
        return 1;
    }
    return 2;
}

# The needs-attention rule: an open task that is Blocked or already past due.
def needs_attention(t: Task, today: str) -> bool {
    if t.status == "Done" {
        return False;
    }
    return t.status == "Blocked" or bool(t.due_date and t.due_date < today);
}


# Blocked first, then soonest due date; undated last. Callers sort by jid
# first, so ties stay deterministic across two requests.
def order_attention(rows: list[Task]) {
    rows.sort(key=lambda (t: Task) { t.due_date or "9999-12-31"; });
    rows.sort(key=lambda (t: Task) { 0 if t.status == "Blocked" else 1; });
}


glob PRIORITY_RANK: dict[str, int] = {"High": 0, "Medium": 1, "Low": 2};

# The table view's user-chosen column sort, over node fields only so it runs
# on the full match set before paging. Priority sorts by urgency; undated
# tasks sort last on the due column. The jid pass underneath keeps ties
# deterministic across pages.
def sort_tasks(rows: list[Task], field: str, reverse: bool) {
    rows.sort(key=lambda (t: Task) { jid(t); });
    if field == "title" {
        rows.sort(key=lambda (t: Task) { t.title.lower(); }, reverse=reverse);
    } elif field == "priority" {
        rows.sort(
            key=lambda (t: Task) { PRIORITY_RANK[t.priority]
                if t.priority in PRIORITY_RANK
                else 1; },
            reverse=reverse
        );
    } elif field == "status" {
        rows.sort(key=lambda (t: Task) { t.status; }, reverse=reverse);
    } elif field == "category" {
        rows.sort(key=lambda (t: Task) { t.category.lower(); }, reverse=reverse);
    } elif field == "estimate" {
        rows.sort(key=lambda (t: Task) { t.estimate; }, reverse=reverse);
    } elif field == "due" {
        rows.sort(
            key=lambda (t: Task) { t.due_date or "9999-12-31"; }, reverse=reverse
        );
    } elif field == "created" {
        rows.sort(key=lambda (t: Task) { t.created_at; }, reverse=reverse);
    } else {
        rows.sort(key=lambda (t: Task) { t.updated_at; }, reverse=reverse);
    }
}


walker ListTasks {
    """One page of tasks. `scope` picks the working set the board renders
    ("working": open plus Done touched in the last `done_days`), the history
    behind its "+N older" ("older": Done before that cutoff, newest first),
    every Done task ("done"), what the Overview calls needs-attention
    (blocked first, then most overdue) ("attention"), or everything ("all").
    `q` matches titles server-side. Filters read node fields first; the
    assignee and project edge hops run only for rows that survived, and
    `to_view()` for the page. `older` on a working page counts the Done rows
    the cutoff left out, under the same filters, so the board's "+N older"
    needs no second call. Every ordering ends in the jid so two rows that
    tie on the sort key cannot swap between one page and the next."""
    has scope: str = "working",
        q: str = "",
        project_id: str = "",
        assignee_id: str = "",
        category: str = "",
        # A tag the task must carry; "estimated" is "" (any), "yes" (has an
        # estimate) or "no" (unestimated).
        tag: str = "",
        estimated: str = "",
        # The table view's column sort; empty keeps the scope's own order.
        sort: str = "",
        sort_dir: str = "asc",
        done_days: int = 7,
        page: int = 1,
        page_size: int = 0,
        reports: list[TaskPage] = [];

    can gather with Root entry {
        (p, size, start, end) = page_bounds(self.page, self.page_size, 50, 500);
        needle = self.q.lower().strip();
        today = today_iso();
        cutoff = done_cutoff(self.done_days);
        picked: list[Task] = [];
        left_out: list[Task] = [];
        for t in [here-->[?:Task]] {
            if needle and needle not in t.title.lower() {
                continue;
            }
            if self.category and t.category != self.category {
                continue;
            }
            if self.tag and self.tag not in t.tags {
                continue;
            }
            if self.estimated == "yes" and t.estimate <= 0.0 {
                continue;
            }
            if self.estimated == "no" and t.estimate > 0.0 {
                continue;
            }
            done = t.status == "Done";
            old = is_older(t, cutoff);
            if self.scope == "working" {
                if old {
                    left_out.append(t);
                    continue;
                }
            } elif self.scope == "older" {
                if not old {
                    continue;
                }
            } elif self.scope == "done" {
                if not done {
                    continue;
                }
            } elif self.scope == "attention" {
                if not needs_attention(t, today) {
                    continue;
                }
            }
            picked.append(t);
        }
        if self.project_id or self.assignee_id {
            picked = self.linked(picked);
            # `older` is only read on an unfiltered working page (the board
            # asks the "older" scope itself once a filter is on), so the
            # edge hops over the whole pre-cutoff history are skipped here.
            left_out = [];
        }
        # Sorts are stable, so the jid pass underneath every other pass is
        # what makes ties deterministic across two requests: without it a
        # row can sit on page 1 for one call and page 2 for the next.
        picked.sort(key=lambda (t: Task) { jid(t); });
        if self.sort {
            # An explicit column sort wins over the scope default and the
            # search rank: the table user asked for this order.
            sort_tasks(picked, self.sort, self.sort_dir == "desc");
        } elif needle {
            picked.sort(key=lambda (t: Task) { t.updated_at; }, reverse=True);
            picked.sort(key=lambda (t: Task) { title_rank(t.title, needle); });
        } elif self.scope == "older" or self.scope == "done" {
            picked.sort(key=lambda (t: Task) { t.updated_at; }, reverse=True);
        } elif self.scope == "attention" {
            order_attention(picked);
        } else {
            order_working(picked);
        }
        report TaskPage(
            rows=hydrate_views(here, picked[start:end]),
            page=p,
            page_size=size,
            has_more=len(picked) > end,
            total=len(picked),
            older=len(left_out)
        );
    }

    # The two edge-hop filters, applied after the node-field ones so the
    # hops run for candidates only.
    def linked(found: list[Task]) -> list[Task] {
        kept: list[Task] = [];
        for t in found {
            if self.project_id {
                owning = [t->:ForProject:->];
                if not owning or jid(owning[0]) != self.project_id {
                    continue;
                }
            }
            if self.assignee_id {
                hit = False;
                for m in [t->:AssignedTo:->] {
                    if jid(m) == self.assignee_id {
                        hit = True;
                    }
                }
                if not hit {
                    continue;
                }
            }
            kept.append(t);
        }
        return kept;
    }
}

# Every Overview number, from tasks already gathered. Tallies attribute each
# task through `links`, so the per-holder edges are read once for the whole
# call rather than once per tally.
def task_totals(
    holder: Root, tasks: list[Task], links: TaskLinks, monday: str
) -> TaskTotals {
    week0 = monday if len(monday) >= 10 else today_iso();
    today = today_iso();
    # Week bounds up front: shift_day parses a date, so calling it per task
    # would be four parses per row.
    starts = [shift_day(week0, -7 * (3 - i)) for i in range(4)];
    ends = [shift_day(starts[i], 7) for i in range(4)];
    by_week = [0, 0, 0, 0];
    open_count = 0;
    overdue_count = 0;
    blocked_count = 0;
    cats: list[str] = [];
    by_project: dict[str, list[Task]] = {};
    by_member: dict[str, list[Task]] = {};
    for t in tasks {
        key = jid(t);
        pid = links.project_id[key] if key in links.project_id else "";
        if pid {
            if pid not in by_project {
                by_project[pid] = [];
            }
            by_project[pid].append(t);
        }
        for who in (links.assignee_ids[key] if key in links.assignee_ids else []) {
            if who not in by_member {
                by_member[who] = [];
            }
            by_member[who].append(t);
        }
        if t.category and t.category not in cats {
            cats.append(t.category);
        }
        if t.status != "Done" {
            open_count = open_count + 1;
            if t.status == "Blocked" {
                blocked_count = blocked_count + 1;
            }
            if t.due_date and t.due_date < today {
                overdue_count = overdue_count + 1;
            }
            continue;
        }
        day = t.updated_at[:10];
        for i in range(4) {
            if day >= starts[i] and day < ends[i] {
                by_week[i] = by_week[i] + 1;
            }
        }
    }
    tallies: list[ProjectTally] = [];
    for pr in [holder-->[?:Project]] {
        pid = jid(pr);
        total = 0;
        done = 0;
        blocked = 0;
        active = 0;
        for t in (by_project[pid] if pid in by_project else []) {
            total = total + 1;
            if t.status == "Done" {
                done = done + 1;
            } elif t.status == "Blocked" {
                blocked = blocked + 1;
            } elif t.status in ACTIVE_STATUSES {
                active = active + 1;
            }
        }
        tallies.append(
            ProjectTally(
                project_id=pid, total=total, done=done, blocked=blocked, active=active
            )
        );
    }
    people: list[MemberTally] = [];
    for m in [holder-->[?:Member]] {
        mid = jid(m);
        mine_open = 0;
        mine_done = 0;
        for t in (by_member[mid] if mid in by_member else []) {
            if t.status != "Done" {
                mine_open = mine_open + 1;
            } elif t.updated_at[:10] >= week0 {
                mine_done = mine_done + 1;
            }
        }
        people.append(
            MemberTally(member_id=mid, open=mine_open, done_in_week=mine_done)
        );
    }
    cats.sort();
    return TaskTotals(
        open=open_count,
        overdue=overdue_count,
        blocked=blocked_count,
        done_by_week=by_week,
        projects=tallies,
        members=people,
        categories=cats
    );
}


walker TaskCounts {
    """The Overview's numbers over the whole history: open tasks, Done per
    week for the four weeks ending in `monday`'s week, and total/done per
    project."""
    has monday: str = "",
        reports: list[TaskTotals] = [];

    can count with Root entry {
        report task_totals(here, [here-->[?:Task]], task_links(here), self.monday);
    }
}


walker CreateTask {
    has title: str,
        category: str = "",
        tags: list[str] = [],
        estimate: float = 0.0,
        priority: str = "Medium",
        status: str = "Backlog",
        step_id: str = "",
        due_date: str = "",
        notes: str = "",
        issue_link: str = "",
        assignee_ids: list[str] = [],
        project_id: str = "",
        reports: list[TaskView] = [];

    can create with Root entry {
        if not self.title.strip() {
            disengage;
        }
        col = self.status if self.status in STATUSES else "Backlog";
        step = "";
        if self.step_id {
            mapped = status_for_step(here, self.step_id);
            if mapped {
                col = mapped;
                step = self.step_id;
            }
        }
        peak = 0.0;
        for t in [here-->[?:Task]] {
            in_column = (
                t.step_id == step if step else (t.status == col and not t.step_id)
            );
            if in_column and t.sort_order > peak {
                peak = t.sort_order;
            }
        }
        stamp = now_iso();
        fresh = here ++> Task(
            title=self.title.strip(),
            category=self.category,
            tags=clean_tags(self.tags),
            estimate=self.estimate,
            priority=self.priority,
            status=col,
            step_id=step,
            due_date=self.due_date,
            notes=self.notes,
            issue_link=self.issue_link,
            created_at=stamp,
            updated_at=stamp,
            sort_order=peak + 1024.0
        );
        on_attached(here, fresh);
        for aid in self.assignee_ids {
            m = resolve(aid);
            if isinstance(m, Member) and owned(here, m) {
                fresh +>:AssignedTo():+> m;
            }
        }
        p = resolve(self.project_id);
        if isinstance(p, Project) and owned(here, p) {
            fresh +>:ForProject():+> p;
        }
        record_task_event(here, fresh, "Added to " + col, stamp);
        report fresh.to_view();
    }
}

walker find_task {
    """Lookup base: resolve the jid once, verify org parentage, then visit.
    Every task mutation subclasses this, jobj resolution alone is NOT
    authorization."""
    has task_id: str = "";

    can locate with Root entry {
        target = resolve(self.task_id);
        if isinstance(target, Task) and owned(here, target) {
            visit [target];
        }
    }
}

walker UpdateTask(find_task) {
    has title: str = "",
        category: str = "",
        tags: list[str] = [],
        estimate: float = 0.0,
        priority: str = "",
        status: str = "",
        step_id: str = "",
        due_date: str = "",
        notes: str = "",
        issue_link: str = "",
        pr_link: str = "",
        reviewer_id: str = "",
        review_due: str = "",
        assignee_ids: list[str] = [],
        project_id: str = "",
        reports: list[TaskView] = [];

    can apply with Task entry {
        # The task's container is the caller's root (root ++> Task).
        owners = [here<--];
        holder = owners[0];
        landing = self.status;
        if self.step_id {
            mapped = status_for_step(holder, self.step_id);
            if mapped {
                landing = mapped;
                here.step_id = self.step_id;
            }
        }
        moved = landing and landing != here.status;
        here.title = self.title;
        here.category = self.category;
        here.tags = clean_tags(self.tags);
        here.estimate = self.estimate;
        here.priority = self.priority;
        here.status = landing;
        here.due_date = self.due_date;
        here.notes = self.notes;
        here.issue_link = self.issue_link;
        here.pr_link = self.pr_link;
        here.review_due = self.review_due;
        rev = resolve(self.reviewer_id);
        if isinstance(rev, Member) and owned(holder, rev) {
            here.reviewer_id = self.reviewer_id;
            here.reviewer_name = rev.name;
        } else {
            here.reviewer_id = "";
            here.reviewer_name = "";
        }
        here.updated_at = now_iso();
        for e in [edge here->:AssignedTo:->] {
            del e;
        }
        for aid in self.assignee_ids {
            m = resolve(aid);
            if isinstance(m, Member) and owned(holder, m) {
                here +>:AssignedTo():+> m;
            }
        }
        for e in [edge here->:ForProject:->] {
            del e;
        }
        p = resolve(self.project_id);
        if isinstance(p, Project) and owned(holder, p) {
            here +>:ForProject():+> p;
        }
        if moved {
            record_task_event(holder, here, "Moved to " + here.status, here.updated_at);
        }
        report here.to_view();
        disengage;
    }
}

walker GetTask(find_task) {
    """One task by jid, owner-checked by find_task. For a deep link to a card
    the board's working set does not hold (older history, a search hit)."""
    has reports: list[TaskView] = [];

    can deliver with Task entry {
        report here.to_view();
        disengage;
    }
}

walker SetMoveInfo(find_task) {
    """The move handoff, all fields optional. Review gets a reviewer, an
    ETA and a PR link; Blocked and Changes Requested get a note. Partial
    by design; anything left empty stays untouched."""
    has reviewer_id: str = "",
        review_due: str = "",
        pr_link: str = "",
        note: str = "",
        reports: list[TaskView] = [];

    can apply with Task entry {
        owners = [here<--];
        holder = owners[0];
        rev = resolve(self.reviewer_id);
        if isinstance(rev, Member) and owned(holder, rev) {
            here.reviewer_id = self.reviewer_id;
            here.reviewer_name = rev.name;
        }
        if self.review_due {
            here.review_due = self.review_due;
        }
        if self.pr_link.strip() {
            here.pr_link = self.pr_link.strip();
        }
        if self.note.strip() {
            # Prepend, never replace: notes is the task's description (or an
            # imported issue body). Newest-first keeps the blocked card's
            # excerpt leading with the reason. Same-line resubmits are no-ops.
            line = "**" + now_iso()[:10] + ":** " + self.note.strip();
            if not here.notes.startswith(line) {
                here.notes = line + ("\n\n" + here.notes if here.notes else "");
            }
        }
        here.updated_at = now_iso();
        sync_task_links(holder, here, self.note.strip());
        report here.to_view();
        disengage;
    }
}

walker MoveTask(find_task) {
    """The drag-drop / arrow-move endpoint. Server-authoritative: a move
    appends to the end of the target column, unless `before_id`/`after_id`
    asks for the spot beside that card there (a stale anchor appends). A
    positioned drop in the card's own column is a pure reorder: no status
    write, no hand-off, no log row, no updated_at bump. `step_id` is the
    flow line column and its mapped status is written too; without it, the
    legacy status-only move."""
    has status: str = "",
        step_id: str = "",
        step_name: str = "",
        before_id: str = "",
        after_id: str = "",
        reports: list[TaskView] = [];

    can move with Task entry {
        # The task's container is the caller's root (root ++> Task).
        owners = [here<--];
        holder = owners[0];
        landing = self.status;
        label = self.status;
        # Read before step_id is rewritten below: a positioned drop in the
        # card's own column stays a reorder for the writes further down.
        positioned = bool(self.before_id or self.after_id);
        reorder = False;
        # Who the move hands the task to: one member, or empty. A list, not
        # an Optional: the checker does not narrow `Member | None` through
        # `if`, so the connect and the `.name` read would not type.
        handed: list[Member] = [];
        if self.step_id {
            mapped = status_for_step(holder, self.step_id);
            # An unknown or foreign step id is a no-op, not a silent move to
            # a blank column.
            if not mapped {
                disengage;
            }
            landing = mapped;
            reorder = positioned and self.step_id == here.step_id;
            # Only a CHANGE of step is a hand-off. Re-dropping a card in its
            # own column (a reorder) must not reassign it.
            if self.step_id != here.step_id {
                step = resolve(self.step_id);
                if isinstance(step, WorkflowStep) {
                    handed = handoff_target(holder, here, step);
                }
            }
            here.step_id = self.step_id;
            label = self.step_name or mapped;
        } else {
            reorder = positioned and not here.step_id and landing == here.status;
            # A status-only move (the assistant, a merged PR, an org with no
            # flow line) must drop whatever step the task was on, or the board
            # keeps drawing it in the old column while the status says
            # otherwise.
            here.step_id = "";
        }
        # The landing column without the moving card, ordered the way the
        # board draws it. Serves both the anchor lookup and the append peak.
        col: list[Task] = [];
        for t in [holder-->[?:Task]] {
            if jid(t) == jid(here) {
                continue;
            }
            in_column = (
                t.step_id == self.step_id
                    if self.step_id
                    else (t.status == landing and not t.step_id)
            );
            if in_column {
                col.append(t);
            }
        }
        col.sort(key=lambda (t: Task) { jid(t); });
        col.sort(key=lambda (t: Task) { t.sort_order; });
        was = here.status;
        here.status = landing;
        here.sort_order = self.landing_sort(col, here);
        if not reorder {
            here.updated_at = now_iso();
        }
        # A hand-off replaces the assignees: the card changes hands, it does
        # not gain a hand. The log line names who it went to.
        note = "Moved to " + label;
        took = False;
        if handed {
            target = handed[0];
            already = [here->:AssignedTo:->];
            if len(already) != 1 or jid(already[0]) != jid(target) {
                for e in [edge here->:AssignedTo:->] {
                    del e;
                }
                here +>:AssignedTo():+> target;
                note = note + " · " + target.name;
                took = True;
            }
        }
        if landing != was or took {
            record_task_event(holder, here, note, here.updated_at);
        }
        report here.to_view();
        disengage;
    }

    # The landing sort: the midpoint beside a valid anchor, the end of the
    # column otherwise. Two neighbors too close for a float midpoint
    # re-spread the whole column at 1024 with the card in its slot.
    def landing_sort(col: list[Task], moving: Task) -> float {
        anchor_id = self.before_id or self.after_id;
        slot = -1;
        for (i, t) in enumerate(col) {
            if jid(t) == anchor_id {
                slot = i;
            }
        }
        if anchor_id and slot >= 0 {
            ahead = bool(self.before_id);
            if ahead {
                hi = col[slot].sort_order;
                lo = col[slot - 1].sort_order if slot > 0 else hi - 2048.0;
            } else {
                lo = col[slot].sort_order;
                hi = col[slot + 1].sort_order if slot + 1 < len(col) else lo + 2048.0;
            }
            mid = (lo + hi) / 2.0;
            if mid > lo and mid < hi {
                return mid;
            }
            at = slot if ahead else slot + 1;
            spread = col[0:at] + [moving] + col[at:];
            n = 0.0;
            out = 0.0;
            for t in spread {
                n = n + 1024.0;
                t.sort_order = n;
                if jid(t) == jid(moving) {
                    out = n;
                }
            }
            return out;
        }
        peak = col[-1].sort_order if col else 0.0;
        return peak + 1024.0;
    }
}

walker DeleteTask(find_task) {
    can remove with Task entry {
        gone = jid(here);
        del here;
        report {"deleted": gone};
        disengage;
    }
}

