"""Shared filter chips + natural-language Ask bar (ConverseQuery)."""

import from "@hugeicons/react" { HugeiconsIcon }
import from "@hugeicons/core-free-icons" {
    SparklesIcon,
    FilterHorizontalIcon,
    SentIcon
}
import from .ui.button { Button }
import from .ui.input { Input }
import from .ui.slider { Slider }
import from .ui.toggle_group { ToggleGroup, ToggleGroupItem }
import from .ui.select { Select, SelectTrigger, SelectValue, SelectContent, SelectItem }
import from .map_markers { sticker_img_url }
import from .pulse_theme {
    all_categories,
    kind_options,
    default_filters,
    future_date_chips
}
sv import from ..services.pulse { converse_query }

def:pub FilterChip(
    label: str, active: bool, onToggle: Callable[[], None], color: str = ""
) -> JsxElement {
    base = "inline-flex h-7 items-center gap-1.5 rounded-full border pl-3 pr-3 text-xs font-medium capitalize transition-colors ";
    tone = "border-foreground bg-foreground text-background"
        if active
        else "bg-card text-muted-foreground hover:text-foreground";
    return
        <button
            type="button"
            onClick={lambda (e: MouseEvent) { onToggle(); }}
            className={base + tone}
        >
            {color
                and <span
                    className="size-2 rounded-full"
                    style={{"backgroundColor": color}}
                />}{label}
        </button>;
}

def:pub StickerChip(
    label: str,
    active: bool,
    onToggle: Callable[[], None],
    dark: bool,
    kind: str = "event",
    categories: list[str] = []
) -> JsxElement {
    tone = (
        "border-foreground bg-foreground text-background"
