        major: str,
        class_year: str,
        preferred_language: str,
        language_chosen: bool,
        arrival_date: str,
        arrival_time: str,
        housing_status: str,
        move_in_date: str,
        area: str,
        needs_airport_ride: bool,
        has_us_phone: bool,
        has_us_bank: bool,
        email_notifications: bool,
        onboarding_done: bool,
