                error = str(r["error"]);
            }
        } except Exception {
            error = "start failed";
        }
        busy = False;
    }
    async def doStopRun() {
        if selRunId == "" { return; }
        busy = True;
        try {
            r = await stop_run(selRunId);
            if bool(r["ok"]) {
                runDetail = r["run"];
                await _loadRuns();
            } else {
                error = str(r["error"]);
            }
        } except Exception {
            error = "stop failed";
        }
        busy = False;
    }
    async def doReattach() {
        if selRunId == "" { return; }
        busy = True;
        error = "";
        try {
            r = await reattach_run(selRunId);
            if bool(r["ok"]) {
                runDetail = r["run"];
                await _loadRuns();
            } else {
                error = str(r["error"]);
            }
        } except Exception {
            error = "reattach failed";
        }
        busy = False;
    }
    async def doPull() {
        if selRunId == "" { return; }
        busy = True;
        error = "";
        try {
            r = await pull_artifacts(selRunId);
            if bool(r["ok"]) { runDetail = r["run"]; }
            else { error = str(r["error"]); }
