"""studio - read-only training-run metrics. Ports server/routers/runs.py.

`def:pub` HTTP endpoints surfacing parsed training artifacts for the Train
HISTORY / MONITOR views: full per-run RunMetrics (loss/val/lr/tps + accuracy curve
+ idiom holdouts + log tail), run listing, and the cross-run compare overlay. All
parsing lives in metrics.sv.jac (runlogs.py); liveness in jobs.sv.jac (procs.py).

Checker notes (jaclang 0.16.1): metrics.parse_train_log returns a dict of `any`
series — pass straight through into the response dict (never re-type); dict values
are `any`, so float/int casts go via `float(str(...))` / `int(str(...))`;
live_status returns dict|None → guard None.
"""

import auth;
import backends;
import jobs;
import json;
import metrics;
import models;
import workspace;
import from pathlib { Path }

def _run_dir(name: str) -> Path {
    return auth.user_results_dir() / name;
}

"""Backend recorded in the job file, else workspace default."""
def _job_backend(name: str, mode: str) -> str {
    jf = _run_dir(name) / f".job-{mode}.json";
    if not jf.exists() { return workspace.training_backend_default(); }
    try {
        job = dict(json.loads(jf.read_text()));
        raw = job.get("backend");
        if raw { return str(raw); }
    } except Exception { }
    return workspace.training_backend_default();
}

def _f(d: dict, k: str) -> float {
    return float(str(d.get(k, 0.0)));
}

def _i(d: dict, k: str) -> int {
    return int(str(d.get(k, 0)));
}

"""True if either the SFT or DPO job file shows status "running"."""
def _is_running(name: str) -> bool {
    for mode in ["sft", "dpo"] {
        jf = auth.user_results_dir() / name / f".job-{mode}.json";
        runlog = auth.user_results_dir() / name / f"run-{mode}.log";
        job = jobs.live_status(jf, runlog);
        if job is not None and str(job.get("status")) == "running" { return True; }
    }
    return False;
}

"""Per-call read-once memo over metrics.last_row, keyed by absolute path.

One _get_run_metrics used to re-read the SAME idiom JSONL up to 5x (_pick_idiom's
2 probes, the isum last_row, and idiom_summary's function+graph probes). *memo* is
a plain local dict, created fresh per call and never shared across requests, so it
needs no invalidation — a file cannot change mid-call in any way this endpoint is
allowed to observe. Result dicts are handed back by reference; nothing here
mutates them."""
def _last_row_once(memo: dict, p: Path) -> dict {
    k = str(p);
    hit = memo.get(k);
    if hit is not None { return dict(hit); }
    row = metrics.last_row(p);
    memo[k] = row;
    return row;
}

"""Best idiom-metrics file for (run_dir, mode) — prefers function holdout over graph,
accepts only files whose last row carries "avg_sim". Ports runlogs.pick_idiom."""
def _pick_idiom(run_dir: Path, mode: str, memo: dict) -> Path | None {
    candidates: list[Path] = [];
    if mode == "dpo" {
        candidates = [run_dir / "dpo" / "idiom-metrics.jsonl", run_dir / "dpo" / "graph-idiom.jsonl"];
    } else {
        candidates = [run_dir / "idiom-metrics.jsonl", run_dir / "graph-idiom.jsonl"];
    }
    for cand in candidates {
        row = _last_row_once(memo, cand);
        if row and "avg_sim" in row { return cand; }
    }
    return None;
}

"""metrics.idiom_summary, but reading through *memo* so a file already read by
_pick_idiom is not read a second time. Same candidate order + same accept test as
metrics.idiom_summary — keep the two in step if that one changes."""
def _idiom_summary_once(memo: dict, run_dir: Path, mode: str, kind: str) -> dict {
    base: Path = run_dir;
    if mode == "dpo" { base = run_dir / "dpo"; }
    candidates: list[Path] = [];
    if kind == "function" {
        candidates = [base / "idiom-metrics.jsonl"];
    } else {
        candidates = [base / "graph-idiom-metrics.jsonl", base / "graph-idiom.jsonl"];
    }
    for cand in candidates {
        row = _last_row_once(memo, cand);
        if row and "avg_sim" in row { return row; }
    }
    return {};
}

def _idiom_obj(s: dict) -> dict {
    return {
        "has": "avg_sim" in s,
        "avg_sim": _f(s, "avg_sim"),
        "idiomatic": _i(s, "idiomatic"),
        "python_shaped": _i(s, "python_shaped"),
        "runs": _i(s, "runs"),
        "total": _i(s, "total")
    };
