def toneForSeverity(severity: str) -> str {
    lowered: str = severity.lower();
    if lowered == "critical" {
        return "danger";
    }
    if lowered == "high" {
        return "warning";
    }
    if lowered == "medium" {
        return "accent";
    }
    return "neutral";
}

