        if isinstance(c, GithubConnection) {
            c.last_sync_at = ctx.stamp;
        }
        report sync_summary(
            [
                len(ctx.linked_tasks),
                ctx.refreshed,
                ctx.auto_added,
                ctx.auto_done_moves,
                scanned,
                pages
            ],
            has_more,
            failure,
            ctx.stamp
        );
    }
}


