"""App shell — workspace switcher + the active workspace's active section.

Workspace list comes from the graph (ui_layout → root --> Workspace, SQLite-persisted).
All section instances stay mounted and are shown/hidden (CSS) so per-section
state survives switches — critically, an in-flight chat SSE stream keeps writing
when you peek at another workspace. The last workspace is remembered in
localStorage; first-ever visit lands on the last discovered attempt (highest NN).
"""

import from react { useEffect, useRef }
sv import from ..models { system_ram }
sv import from ..workspace { ui_layout }
import from ..auth_session { handleUnauthorized }
import from .NavRail { NavRail }
import from .WorkspaceBar { WorkspaceBar }
import from .Offline { Offline }
import from .SectionMount { SectionMount }
import from .WorkspaceSettings { WorkspaceSettings }
import from .AssistantPanel { AssistantPanel }
import from .jms.ApiKeyModal { ApiKeyModal }
import from .shared.CommandPalette { CommandPalette }
import from .shared.Shortcuts { ShortcutSheet, isTypingTarget, toggleTheme }
import from .shared.Toast { ToastHost }
import from .shared.JobWatch { JobWatch }

"""Fresh per-workspace section pointers (first section in each workspace)."""
def _defaultSections(layout: any) -> dict {
    nd: dict = {};
    for ws in list(layout["workspaces"]) {
        wd = ws as dict;
        wid = str(wd["id"]);
        secs = list(wd["sections"]);
        first = secs[0] as dict if len(secs) > 0 else {"id": "chat"};
        nd[wid] = str(first["id"]);
    }
    return nd;
}

def _mergeSections(layout: any, prev: dict) -> dict {
    nd: dict = {};
    for ws in list(layout["workspaces"]) {
        wd = ws as dict;
        wid = str(wd["id"]);
        if wid in prev {
            nd[wid] = str(prev[wid]);
        } else {
            secs = list(wd["sections"]);
            first = secs[0] as dict if len(secs) > 0 else {"id": "chat"};
            nd[wid] = str(first["id"]);
        }
    }
    return nd;
}

def _isWorkspaceId(layout: any, w: str) -> bool {
    for wid in list(layout["workspace_ids"]) {
        if str(wid) == w { return True; }
    }
    return False;
}

"""Resolve a workspace id OR label (case-insensitive) to its id, so the assistant
can say "SFT/DPO" or "04" and land the same place. Empty string if no match."""
def _resolveWs(layout: any, x: str) -> str {
    if layout is None or not x { return ""; }
    want = x.strip().lower();
    for ws in list(layout["workspaces"]) {
        wd = ws as dict;
        if str(wd["id"]).lower() == want or str(wd["label"]).lower() == want {
            return str(wd["id"]);
        }
    }
    return "";
}

"""Section ids of one workspace, in rail order — the `[` / `]` cycle order."""
def _sectionIds(layout: any, ws: str) -> list {
    out: list = [];
    if layout is None { return out; }
    for w in list(layout["workspaces"]) {
        wd = w as dict;
        if str(wd["id"]) == ws {
            for sec in list(wd["sections"]) {
                sd = sec as dict;
                out.append(str(sd["id"]));
            }
        }
    }
    return out;
}

"""Command-palette menu for the Experiments surface. Order here IS display
order (the palette does not re-rank), so categories stay contiguous."""
def _expActions(layout: any, workspace: str) -> list {
    out: list = [];
    if layout is None { return out; }
    n: int = 0;
    for w in list(layout["workspaces"]) {
        wd = w as dict;
        wid = str(wd["id"]);
        n += 1;
        out.append({
            "id": "ws:" + wid,
            "group": "WORKSPACE",
            "label": wid + " " + str(wd["label"]),
            "hint": str(n) if n <= 6 else ""
        });
    }
    for w in list(layout["workspaces"]) {
        wd = w as dict;
        if str(wd["id"]) != workspace { continue; }
        for sec in list(wd["sections"]) {
            sd = sec as dict;
            out.append({
                "id": "sec:" + str(sd["id"]),
                "group": "SECTION",
                "label": str(sd["label"]),
                "hint": ""
            });
        }
    }
    out.append({"id": "nav:hub", "group": "GO TO", "label": "Hub — the landing screen", "hint": "g h"});
    out.append({"id": "nav:jms", "group": "GO TO", "label": "JMS — project pipeline", "hint": ""});
    out.append({"id": "ui:settings", "group": "SETTINGS", "label": "Workspaces settings drawer", "hint": ""});
    out.append({"id": "ui:keys", "group": "SETTINGS", "label": "Provider API keys", "hint": ""});
    out.append({"id": "ui:theme", "group": "SETTINGS", "label": "Toggle light / dark", "hint": "t"});
    out.append({"id": "ui:help", "group": "SETTINGS", "label": "Keyboard shortcuts", "hint": "?"});
    return out;
}

"""Cross-surface navigation. frontend.cl.jac routes on the URL hash and listens
for hashchange, so writing the hash is the whole hop."""
def _goHash(h: str) -> None {
    try {
        w: any = window;
        w.location.hash = h;
    } except Exception { }
}

"""Flatten workspace × section mounts for a single JSX iteration pass."""
def _allSlots(layout: any) -> list[dict] {
    out: list[dict] = [];
    for ws in list(layout["workspaces"]) {
        wd = ws as dict;
        wsId = str(wd["id"]);
        dm = str(wd["default_model"]);
        for sec in list(wd["sections"]) {
            sd = sec as dict;
            out.append({
                "wsId": wsId,
                "secId": str(sd["id"]),
                "component": str(sd["component"]),
                "defaultModel": dm
            });
        }
    }
    return out;
}

def:pub AppShell(onHub: any = None) -> JsxElement {
    has layout: any = None,
        workspace: str = "03",
        sections: dict = {},
        online: int = -1,
        settingsOpen: bool = False,
        paletteOpen: bool = False,
        sheetOpen: bool = False,
        keyModalOpen: bool = False;

    async def probe -> None {
        try {
            await system_ram();
            online = 1;
        } except Exception {
            restored: bool = False;
            restored = await handleUnauthorized();
            if restored {
                try {
                    await system_ram();
                    online = 1;
                    return;
                } except Exception { }
            }
            online = 0;
        }
    }

    def handleLayoutChange(ly: any) -> None {
        sections = _mergeSections(ly, sections);
        layout = ly;
        if not _isWorkspaceId(ly, workspace) {
            workspace = str(ly["default_workspace"]);
        }
    }

    async can with entry {
        doc: any = document;
        win: any = window;
        mode: str = "dark";
        try {
            saved: any = win.localStorage.getItem("jacml.mode");
            if saved { mode = str(saved); }
            elif win.matchMedia and win.matchMedia("(prefers-color-scheme: light)").matches { mode = "light"; }
        } except Exception { }
        if mode == "dark" { doc.documentElement.classList.add("dark"); }
        else { doc.documentElement.classList.remove("dark"); }
        doc.body.classList.add("antialiased");
        try {
            ly = await ui_layout();
            layout = ly;
            workspace = str(ly["default_workspace"]);
            sections = _defaultSections(ly);
            w: any = window;
            saved: any = w.localStorage.getItem("jacml.workspace");
            if saved and _isWorkspaceId(ly, str(saved)) {
                workspace = str(saved);
            }
        } except Exception { }
        await probe();
    }

    # Liveness poller. Deliberately NOT inside `can with entry`: that block's
    # compiled cleanup can't see an id assigned later, so every hub↔experiments
    # round-trip (which unmounts AppShell) used to leak another permanent 3s
    # timer — and a zombie probe() failing calls handleUnauthorized() →
    # signalExpired() → jacLogout(), i.e. an unmounted shell could log the user
    # out. Effect-local id + cleanup, same shape as Cloud/Train.
    useEffect(lambda {
        iv: any = setInterval(lambda { probe(); }, 3000);
        return lambda { clearInterval(float(str(iv))); };
    }, []);

    def goWorkspace(wsId: str) -> None {
        workspace = wsId;
        try {
            win: any = window;
            win.localStorage.setItem("jacml.workspace", wsId);
        } except Exception { }
    }

    def go(s: str) -> None {
        if layout is None { return; }
        nd: dict = {};
        for ws in list(layout["workspaces"]) {
            wd = ws as dict;
            wid = str(wd["id"]);
            nd[wid] = str(sections[wid]) if wid in sections else "chat";
        }
        nd[workspace] = s;
        sections = nd;
    }

    """Visibility class for one section slot.

    NO `reveal` here. Every section instance stays mounted and is toggled with
    `hidden` (display:none) — and a CSS animation RESTARTS whenever an element
    goes display:none -> displayed. `.reveal` is `opacity:0` + a 0.6s fadeInUp,
    so putting it on this slot replayed that animation on EVERY section and
    workspace switch: the whole content pane snapped to opacity 0 and crawled
    back over ~600ms, exposing the bare page background — pure black in dark
    mode. That read as the app "going black" on every tab click. This was latent
    until the Tailwind build was fixed: while `hidden` emitted no CSS, sections
    were never actually display:none, so the animation only ever ran once.
    Section switching is now instant, which is what a tab swap should be.
    """
    def slot(ws: str, s: str) -> str {
        vis = ws == workspace and s == str(sections[ws]);
        return "flex min-w-0 flex-1" if vis else "hidden";
    }

    """Cycle the active workspace's sections (the `[` / `]` bindings)."""
    def moveSection(delta: int) -> None {
        if layout is None { return; }
        ids: list = _sectionIds(layout, workspace);
        if len(ids) == 0 { return; }
        curId: str = str(sections[workspace]) if workspace in sections else "";
        at: int = 0;
        i: int = 0;
        for sid in ids {
            if str(sid) == curId { at = i; }
            i += 1;
        }
        go(str(ids[(at + delta + len(ids)) % len(ids)]));
    }

    """The `1`–`6` bindings: Nth workspace in layout order."""
    def wsByIndex(n: int) -> None {
        if layout is None { return; }
        ids: list = list(layout["workspace_ids"]);
        if n >= 0 and n < len(ids) { goWorkspace(str(ids[n])); }
    }

    def goHub -> None {
        if onHub is not None { onHub(); }
    }

    """Single dispatch point for every palette entry built by _expActions."""
    def runAction(aid: str) -> None {
        if aid.startswith("ws:") { goWorkspace(aid[3:]); return; }
        if aid.startswith("sec:") { go(aid[4:]); return; }
        if aid == "nav:hub" { goHub(); return; }
        if aid == "nav:jms" { _goHash("jms"); return; }
        if aid == "ui:settings" { settingsOpen = True; return; }
        if aid == "ui:keys" { keyModalOpen = True; return; }
        if aid == "ui:theme" { toggleTheme(); return; }
        if aid == "ui:help" { sheetOpen = True; return; }
    }

    # `g h` chord state lives in a ref, never a `has`: the keydown listener is a
    # closure and a `has` read inside it goes stale. The listener is added and
    # REMOVED in the same effect; deps carry every value the handler reads, so
    # the registered closure is always the current one.
    gRef: any = useRef(0.0);
    useEffect(lambda {
        doc: any = document;
        onKey = lambda(e: any) {
            k: str = str(e.key);
            meta: bool = bool(e.metaKey) or bool(e.ctrlKey);
            if meta and (k == "k" or k == "K") {
                e.preventDefault();
                paletteOpen = not paletteOpen;
                return;
            }
            if meta or bool(e.altKey) { return; }
            # never steal a key the user is typing into a field
            if isTypingTarget(e) { return; }
            if paletteOpen { return; }
            if k == "?" { sheetOpen = not sheetOpen; return; }
            if sheetOpen { return; }
            if k == "g" { gRef.current = Date.now(); return; }
            if k == "h" {
                if (Date.now() - float(str(gRef.current))) < 900.0 {
                    gRef.current = 0.0;
                    goHub();
                }
                return;
            }
            if k == "t" { toggleTheme(); return; }
            if k == "[" { moveSection(-1); return; }
            if k == "]" { moveSection(1); return; }
            if k in ["1", "2", "3", "4", "5", "6"] { wsByIndex(int(k) - 1); return; }
        };
        doc.addEventListener("keydown", onKey);
        return lambda { doc.removeEventListener("keydown", onKey); };
    }, [layout, workspace, sections, paletteOpen, sheetOpen]);

    if online == 0 {
        return <Offline />;
    }
    if online == -1 or layout is None {
        return <div className="h-screen bg-background" />;
    }

    # Nav bridge for the assistant widget: re-published every render so the
    # closures always capture the LATEST layout/workspace/sections (no React
    # stale-closure). The widget calls window.__jmsNav.goWorkspace/go to drive
    # experiments navigation; label→id resolution happens here where layout lives.
    try {
        wbridge: any = window;
        wbridge.__jmsNav = {
            "goWorkspace": lambda(x: str) -> None {
                rid = _resolveWs(layout, x);
                if rid { goWorkspace(rid); }
            },
            "go": go
        };
    } except Exception { }

    # ⚙ WORKSPACES is a TOGGLE, not an opener: it used to hard-set
    # `settingsOpen = True`, so a second click on it was a no-op (only ✕ / Esc /
    # the scrim closed the drawer). The palette entry below stays open-only —
    # "Workspaces settings drawer" should never mean "close it".
    # The toggle only actually WORKS because WorkspaceSettings' overlay starts at
    # --topbar-h instead of inset-0: while it was `fixed inset-0`, the drawer
    # panel painted over this very button and swallowed the second click.
    return <div className="flex h-screen flex-col overflow-hidden" data-ws={workspace}>
        <WorkspaceBar
            layout={layout}
            workspace={workspace}
            onWorkspace={goWorkspace}
            onSettings={lambda -> None { settingsOpen = not settingsOpen; }}
            onHub={onHub}
        />

        <div className="flex min-h-0 flex-1 overflow-hidden">
            <NavRail
                layout={layout}
                workspace={workspace}
                section={str(sections[workspace])}
                onSection={go}
            />

            {for slotInfo in _allSlots(layout) {
                wsId = str(slotInfo["wsId"]);
                sid = str(slotInfo["secId"]);
                comp = str(slotInfo["component"]);
                dm = str(slotInfo["defaultModel"]);
                active = wsId == workspace and sid == str(sections[wsId]);
                <div key={wsId + "|" + sid} className={slot(wsId, sid)}>
                    <SectionMount
                        component={comp}
                        workspace={wsId}
                        defaultModel={dm}
                        active={active}
                    />
                </div>
            }}
        </div>

        <WorkspaceSettings
            open={settingsOpen}
            layout={layout}
            activeWorkspace={workspace}
            onClose={lambda -> None { settingsOpen = False; }}
            onChanged={handleLayoutChange}
        />

        {keyModalOpen and <ApiKeyModal open={True} onClose={lambda { keyModalOpen = False; }} />}

        <CommandPalette
            open={paletteOpen}
            actions={_expActions(layout, workspace)}
            onRun={runAction}
            onClose={lambda { paletteOpen = False; }}
        />

        <ShortcutSheet open={sheetOpen} onClose={lambda { sheetOpen = False; }} />

        <ToastHost />
        <JobWatch />

        <AssistantPanel pageContext={"Experiments surface · workspace " + workspace + (" · section " + str(sections[workspace]) if workspace in sections else "")} />
    </div>;
}

"""studio - JMS workspace grouping (OSP graph, per-user, LEAN).

JMS workspaces exist to GROUP projects at the top nav bar (WorkspaceBar /
NavRail are already generic renderers over a `{workspaces:[{id,label,accent}]}`
layout dict — see workspace.sv.jac's `ui_layout`). Unlike Experiments'
`Workspace` node, a `JmsWorkspace` carries NO `WorkspaceSection` children and
NO `default_model`/`files` — a project keeps its own internal stage rail
(SOURCES/GENERATE/CURATE/TRAIN/EVAL), so there is nothing here to mount.

Graph shape: `root ++> JmsWorkspace`, one layer, seeded once (backfill-safe —
new `_SEED_JMS_WORKSPACES` entries get added to an already-seeded graph without
duplicating what's there, mirroring `workspace.sv.jac:_ensure_workspaces_seeded`).
Every read/write walks the CALLER'S OWN root (`[root -->][?:JmsWorkspace]`), so
this is multi-tenant isolated for free — same guarantee jms_projects.sv.jac
relies on.

This task (B1) does NOT touch jms_projects.sv.jac: a project's `group_id`
field + the workspace-filtered `list_projects`/`create_project` land in a
later task. `delete_jms_workspace` here only removes the `JmsWorkspace` node.

Checker notes (jaclang 0.16.1, same as jms_projects.sv.jac): `root ++> X(...)`
returns a LIST — unwrap `[0]` before touching the new node; dict values
crossing the RPC boundary are `any`.
"""

# ------------------------------------------------------------------- views -----
"""One workspace as the top nav bar sees it: just enough to render a tile."""
obj JmsWorkspaceView {
    has id: str = "",
        label: str = "",
        accent: str = "";
}

# ------------------------------------------------------------------- nodes -----
node JmsWorkspace {
    has wid: str = "",
        label: str = "",
        accent: str = "",
        sort_order: int = 0;
}

# --------------------------------------------------------------- seed data -----
# Fixed single-workspace seed. Mirrors workspace.sv.jac's backfill-safe seeding
# shape so a future entry can be appended here without duplicating "main" on an
# already-seeded graph.
glob _SEED_JMS_WORKSPACES: list[dict] = [
    {"wid": "main", "label": "MAIN", "accent": "ws01", "sort_order": 0}
];

# ------------------------------------------------------------------ finders ----
def _all_jms_workspaces() -> list[JmsWorkspace] {
    wss = [w for w in [root -->][?:JmsWorkspace]];
    wss.sort(key=lambda w: JmsWorkspace -> str {
        return str(w.sort_order).zfill(6) + w.wid;
    });
    return wss;
}

def _find_jms_workspace(wid: str) -> JmsWorkspace | None {
    for w in [root -->][?:JmsWorkspace] {
        if w.wid == wid { return w; }
    }
    return None;
}

# ------------------------------------------------------------------ seeding ----
"""Create the fixed workspace set on the caller's root the first time
(idempotent). Backfill-safe: if the graph already holds JmsWorkspace nodes,
only specs whose wid is missing get added (so a future new seed entry isn't
skipped forever on an already-seeded graph) — mirrors
workspace.sv.jac:_ensure_workspaces_seeded."""
def _seed_jms_workspaces() -> None {
    existing = [w for w in [root -->][?:JmsWorkspace]];
    present: list[str] = [];
    for w in existing { present.append(w.wid); }
    for spec in _SEED_JMS_WORKSPACES {
        if str(spec["wid"]) not in present {
            root ++> JmsWorkspace(
                wid=str(spec["wid"]), label=str(spec["label"]),
                accent=str(spec["accent"]), sort_order=int(str(spec["sort_order"]))
            );
        }
    }
}

def _jms_workspace_view(w: JmsWorkspace) -> JmsWorkspaceView {
    return JmsWorkspaceView(id=w.wid, label=w.label, accent=w.accent);
}

def _next_jms_workspace_id() -> str {
    max_n = 0;
    for w in [root -->][?:JmsWorkspace] {
        try {
            n = int(w.wid);
            if n > max_n { max_n = n; }
        } except Exception { }
    }
    nxt = max_n + 1;
    return ("0" + str(nxt)) if nxt < 10 else str(nxt);
}

def _next_jms_accent() -> str {
    accents = ["ws01", "ws02", "ws03", "ws04", "ws05", "ws06"];
    n = len([root -->][?:JmsWorkspace]);
    return accents[n % len(accents)];
}

# ---------------------------------------------------------------- endpoints ----
"""JMS workspace registry for the top nav bar — workspaces + a default. Reads
from the graph (root --> JmsWorkspace), seeding on first call. Plain `def` →
caller's isolated root, so workspaces are per-user."""
def jms_ui_layout() -> dict {
    _seed_jms_workspaces();
    wss = [_jms_workspace_view(w) for w in _all_jms_workspaces()];
    ids: list[str] = [];
    for w in wss { ids.append(w.id); }
    default_ws = wss[0].id if len(wss) > 0 else "main";
    return {
        "default_workspace": default_ws,
        "workspace_ids": ids,
        "workspaces": wss
    };
}

"""Add a new JMS workspace, sorted after every existing one. Returns the
refreshed layout dict (same shape as `jms_ui_layout`)."""
def create_jms_workspace(label: str, accent: str) -> dict {
    _seed_jms_workspaces();
    wid = _next_jms_workspace_id();
    acc = accent if accent else _next_jms_accent();
    root ++> JmsWorkspace(
        wid=wid, label=label, accent=acc, sort_order=len(_all_jms_workspaces())
    );
    return jms_ui_layout();
}

"""Patch label/accent on an existing JMS workspace (unknown wid is a no-op).
Returns the refreshed layout dict."""
def update_jms_workspace(wid: str, label: str, accent: str) -> dict {
    _seed_jms_workspaces();
    w = _find_jms_workspace(wid);
    if w {
        w.label = label;
        w.accent = accent;
    }
    return jms_ui_layout();
}

"""Delete a JMS workspace node (refuses to drop the last one, mirroring
workspace.sv.jac's delete_workspace floor). Projects are NOT touched by this
task — reassigning their group_id to "" lands with jms_projects.sv.jac's
group_id field in a later task. Returns the refreshed layout dict."""
def delete_jms_workspace(wid: str) -> dict {
    _seed_jms_workspaces();
    if len(_all_jms_workspaces()) > 1 {
        w = _find_jms_workspace(wid);
        if w { del w; }
    }
    return jms_ui_layout();
}

"""Persist a new top-bar tile order. Unknown ids are ignored. Returns the
refreshed layout dict."""
def reorder_jms_workspaces(ids: list) -> dict {
    _seed_jms_workspaces();
    for (i, wid) in enumerate(ids) {
        w = _find_jms_workspace(str(wid));
        if w { w.sort_order = i; }
    }
    return jms_ui_layout();
}

