"""Staffing-needs editor and the employee's standing availability rules (Availability Agent)."""

import from react { useEffect, useState }
import from "lucide-react" { Plus, Trash2 }
import from web.lib.api { api, errMsg }
import from web.lib.time { DAYS_LONG, TIME_OPTIONS, hm, jsSort }
import from web.components.ui { Stepper, useToast }

glob:pub JS: any = globalThis;

def _by_end_desc(a: any, b: any) -> int {
    return b.end - a.end;
}

def _by_start(a: any, b: any) -> int {
    return a.n.start - b.n.start;
}

"""needs: [{day, start, end, headcount, position_id?}] -- roles: [{id, name}]"""
def:pub NeedsEditor(needs: any, onChange: any, roles: any = None) -> JsxElement {
    role_list: any = roles or [];
    def update(i: int, patch: any) -> None {
        out: list[any] = [];
        for (j, n) in enumerate(needs) {
            out.append(JS.Object.assign({}, n, patch) if j == i else n);
        }
        onChange(out);
    }
    def remove(i: int) -> None {
        onChange([n for (j, n) in enumerate(needs) if j != i]);
    }
    def add(day: int) -> None {
        same: any = [n for n in needs if n.day == day];
        same = jsSort(same, _by_end_desc);
        last: any = same[0] if same.length else None;
        start: int = JS.Math.min(last.end, 20 * 60) if last else 9 * 60;
        extra: any = {
            "day": day, "start": start, "end": JS.Math.min(start + 4 * 60, 24 * 60),
            "headcount": last.headcount if last else 1,
            "position_id": (last.position_id or None) if last else None
        };
        onChange(JS.Array.prototype.concat.call(needs, [extra]));
    }
    def copyMonday() -> None {
        mon: any = [n for n in needs if n.day == 0];
        rest: any = [n for n in needs if n.day > 4];
        out: list[any] = [];
        for d in [0, 1, 2, 3, 4] {
            for n in mon {
                out.append(JS.Object.assign({}, n, {"day": d}));
            }
        }
        onChange(JS.Array.prototype.concat.call(out, rest));
    }
    has_monday: bool = any([n.day == 0 for n in needs]);
    def addTo(day: int) -> any {
        return lambda (e: MouseEvent) { add(day); };
    }
    def setNum(i: int, field: str) -> any {
        return lambda (e: ChangeEvent) {
            patch: any = {};
            patch[field] = JS.Number(e.target.value);
            update(i, patch);
        };
    }
    def setCount(i: int) -> any {
        return lambda (v: int) { update(i, {"headcount": v}); };
    }
    def setRole(i: int) -> any {
        return lambda (e: ChangeEvent) { update(i, {"position_id": e.target.value or None}); };
    }
    def removeAt(i: int) -> any {
        return lambda (e: MouseEvent) { remove(i); };
    }
    <div className="stack g16">
        <div className="row end">
            <button type="button" className="btn sm" onClick={lambda (e: MouseEvent) { copyMonday(); }} disabled={not has_monday}>Copy Monday to weekdays</button>
        </div>
        {for (day, label) in enumerate(DAYS_LONG) {
            rows: any = [{"n": n, "i": i} for (i, n) in enumerate(needs) if n.day == day];
            rows = jsSort(rows, _by_start);
            <section key={day} className="card tight">
                <div className="row between">
                    <h3 className="t-card">{label}</h3>
                    <button type="button" className="btn text sm" onClick={addTo(day)}><Plus size={14} strokeWidth={1.5} />Add block</button>
                </div>
                {rows.length == 0 and <div className="ink-2 mt8">No one needed.</div>}
                <div className="stack g8 mt8">
                    {for row in rows {
                        n: any = row["n"];
                        ends: any = [t for t in TIME_OPTIONS if t > n.start];
                        if n.end <= n.start {
                            ends = JS.Array.prototype.concat.call(ends, [n.end]);
                        }
                        <div key={row["i"]} className="row g8 wrap">
                            <select className="select" style={{"width": 104}} aria-label="Start time" value={n.start}
                                onChange={setNum(row["i"], "start")}>
                                {for t in TIME_OPTIONS { <option key={t} value={t}>{hm(t)}</option> }}
                            </select>
                            <span className="ink-2">to</span>
                            <select className="select" style={{"width": 104}} aria-label="End time" value={n.end}
                                onChange={setNum(row["i"], "end")}>
                                {for t in ends { <option key={t} value={t}>{hm(t)}</option> }}
                            </select>
                            <Stepper value={n.headcount} min={1} max={50} onChange={setCount(row["i"])} label="People needed" />
                            <span className="ink-2 hide-mobile">{"person" if n.headcount == 1 else "people"}</span>
                            {role_list.length > 0 and <select className="select" style={{"width": 150}} aria-label="Role" value={n.position_id or ""}
                                onChange={setRole(row["i"])}>
                                <option value="">Any role</option>
                                {for r in role_list { <option key={r.id} value={r.id}>{r.name}</option> }}
                            </select>}
                            <button type="button" className="btn icon text" style={{"color": "var(--ink-2)", "marginLeft": "auto"}} aria-label="Delete block" onClick={removeAt(row["i"])}>
                                <Trash2 size={16} strokeWidth={1.5} />
                            </button>
                            {n.end <= n.start and <span className="helper c-block" style={{"width": "100%"}}>This block ends before it starts.</span>}
                        </div>
                    }}
                </div>
            </section>
        }}
    </div>
}

# ---------------- standing availability rules (Availability Agent) ----------------
def:pub AvailabilityNotes() -> JsxElement {
    has note: str = "";
    has savedNote: str = "";
    has rules: list[any] = [];
    has parsing: bool = False;
    toast: any = useToast();

    async can with entry {
        try {
            d: any = await api("get_availability");
            note = d.note;
            savedNote = d.note;
            rules = d.rules;
        } except Exception {
            return;
        }
    }

    async def parse() -> None {
        if note == savedNote {
            return;
        }
        parsing = True;
        try {
            r: any = await api("parse_availability_note", {"note": note});
            rules = r.rules;
            savedNote = note;
        } except Exception as e {
            toast(errMsg(e), False);
        }
        parsing = False;
    }

    async def removeRule(r: any) -> None {
        await api("remove_availability_rule", {"day": r.day, "start": r.start, "end": r.end});
        rules = [x for x in rules if x is not r];
    }

    def removeClick(r: any) -> any {
        return lambda (e: MouseEvent) { removeRule(r); };
    }

    <div className="field">
        <label htmlFor="note">Anything that's true every week?</label>
        <textarea id="note" className="textarea" placeholder="e.g. No Fridays before 10 AM — I have lab." value={note}
            onChange={lambda (e: ChangeEvent) { note = e.target.value; }} onBlur={lambda (e: FocusEvent) { parse(); }} />
        {parsing and <div className="helper mono">Availability Agent is reading this…</div>}
        {not parsing and len(rules) > 0 and <div className="stack g8 mt4">
            <span className="mono ink-3">Understood by Availability Agent</span>
            <div className="row g8 wrap">
                {for (i, r) in enumerate(rules) {
                    <span key={i} className="rule-chip">{r.label}<button type="button" aria-label={"Remove " + r.label} onClick={removeClick(r)}>×</button></span>
                }}
            </div>
        </div>}
        {not parsing and savedNote and note == savedNote and len(rules) == 0 and <div className="helper">No time limits found in this note.</div>}
    </div>
}

"""GitHub walkers: connect an installation, read issues and PRs, import issues
as tasks, open an issue from a task. Auth is an App installation (tokens minted
per call, never reported). Every walker but GithubStatus reports ONE envelope,
{"ok": True, ...} or {"ok": False, "error", "message"}. Nothing polls."""

import from models {
    Project,
    Member,
    Repo,
    Task,
    TaskView,
    WorkflowStep,
    GithubConnection,
    GithubConnectionView,
    GhRepoRow,
    GhIssueRow,
    GhPrRow,
    HasRepo,
    AssignedTo,
    ForProject,
    resolve,
    on_attached,
    owned,
    repo_view
}
import from walkers.util { now_iso, minutes_since, clean_tags }
import from walkers.log { record_task_event }
import from walkers.tasks { find_task, status_for_step }
import from walkers.ghutil {
    missing_config,
    install_url,
    new_state,
    installation_token,
    forget_installation,
    valid_full_name,
    gh_request,
    exchange_code,
    user_owns_installation,
    clock,
    bind_installation,
    unbind_installation,
    root_for_installation
}
import from constants { STATUSES, MERGE_SUGGEST_STATUSES }

# An install round trip that has sat unfinished for this long is a stale tab,
# not a person mid-flow.
glob INSTALL_WINDOW_MINUTES: float = 15.0,
     PAGE_SIZE: int = 50,
     IMPORT_CAP: int = 25,
     # One sync call reads at most this many 100-item pages across every
     # repo, and issues no new request once this many seconds have passed;
     # the repo cursors carry the rest to the next call (has_more).
     SYNC_PAGE_BUDGET: int = 5,
     SYNC_SECONDS_BUDGET: float = 8.0,
     # A board mounts twice on a full page load; the auto pass skips itself
     # when a sync just ran so the double mount costs one GitHub call.
     AUTO_SYNC_COOLDOWN_MINUTES: float = 1.0,
     # Sub-issue child lists fetched per sync, stalest families first by
     # walk order. Counts are free (they ride the issue list); only the
     # child links cost a call, and only when a family changed.
     SUB_ISSUE_CAP: int = 20,
     # Installations this process has already seen in the index, so the
     # status call costs a store read once rather than every page open.
     BOUND_SEEN: dict[str, bool] = {};

# Ceilings, because walker endpoints have no built-in pagination or rate
# limiting: a hostile client should only ever burn its own installation's
# GitHub quota.
# --------------------------------------------------------------- connection

def connection_of(holder: Root) -> any {
    found = [holder-->[?:GithubConnection]];
    return found[0] if found else None;
}


def connection_view(c: any) -> GithubConnectionView {
    gaps = missing_config();
    configured = not gaps;
    if not isinstance(c, GithubConnection) or c.installation_id == 0 {
        return GithubConnectionView(
            connected=False, configured=configured, missing_config=gaps
        );
    }
    return GithubConnectionView(
        connected=True,
        account_login=c.account_login,
        account_avatar=c.account_avatar,
        status=c.status,
        connected_at=c.connected_at,
        last_sync_at=c.last_sync_at,
        configured=configured,
        missing_config=gaps
    );
}


# Workspaces connected before the installation index existed get their
# row on the next status call, once per process; no migration step. A store
# hiccup leaves the memo unset so the next call tries again.
def ensure_bound(holder: Root, c: any) -> None {
    if not isinstance(c, GithubConnection) or c.installation_id == 0 {
        return;
    }
    key = str(c.installation_id);
    if key in BOUND_SEEN {
        return;
    }
    if root_for_installation(c.installation_id)
        or bind_installation(c.installation_id, jid(holder)) {
        BOUND_SEEN[key] = True;
    }
}


# The token for this workspace's installation, or "" when the workspace is
# not connected. A 401 anywhere flips the connection to "invalid" so every
# GitHub surface can show one reconnect banner.
def token_of(c: any) -> str {
    if not isinstance(c, GithubConnection) or c.installation_id == 0 {
        return "";
    }
    return installation_token(c.installation_id);
}


def mark_invalid(c: any, result: dict[str, any]) -> None {
    if not isinstance(c, GithubConnection) {
        return;
    }
    if result.get("error") == "unauthorized" or result.get("error") == "not_found" {
        c.status = "invalid";
    }
}


def not_connected -> dict[str, any] {
    return {
        "ok": False,
        "error": "not_connected",
        "message": "Connect the GitHub App first."
    };
}


walker GithubStatus {
    """Cheap, no GitHub call: every page showing GitHub UI opens with it."""
    has reports: list[GithubConnectionView] = [];

    can look with Root entry {
        c = connection_of(here);
        ensure_bound(here, c);
        report connection_view(c);
    }
}


walker StartGithubInstall {
    """Hands back the install URL carrying a one-shot nonce, stored server-side
    and burned on use so a forged callback cannot bind another installation."""
    has reports: list[dict[str, any]] = [];

    can begin with Root entry {
        gaps = missing_config();
        if gaps {
            report {
                "ok": False,
                "error": "not_configured",
                "message": "The server is missing " + ", ".join(gaps) + ".",
                "missing": gaps
            };
            disengage;
        }
        existing = [here-->[?:GithubConnection]];
        target = existing[0] if existing else None;
        if not target {
            target = here ++> GithubConnection();
            on_attached(here, target);
        }
        nonce = new_state();
        target.pending_state = nonce;
        target.pending_at = now_iso();
        report {"ok": True, "url": install_url(nonce)};
    }
}


walker CompleteGithubInstall {
    """Finish the round trip GitHub redirected back from. Two checks before
    anything is stored: the nonce matches the one this workspace issued (CSRF),
    and the GitHub user can actually see the claimed installation, since
    installation ids are small integers a forged link could otherwise pick."""
    has code: str = "",
        installation_id: int = 0,
        state: str = "",
        reports: list[dict[str, any]] = [];

    can finish with Root entry {
        existing = [here-->[?:GithubConnection]];
        target = existing[0] if existing else None;
        if not isinstance(target, GithubConnection) {
            report {
                "ok": False,
                "error": "no_pending_install",
                "message": "Start the install from this page first."
            };
            disengage;
        }
        # One shot: burn the nonce before doing any work with it, so a
        # replayed callback cannot take a second run at the checks.
        expected = target.pending_state;
        stamp = target.pending_at;
        target.pending_state = "";
        target.pending_at = "";
        if not expected or self.state != expected {
            report {
                "ok": False,
                "error": "bad_state",
                "message": "That install link did not come from this workspace."
            };
            disengage;
        }
        if minutes_since(stamp) > INSTALL_WINDOW_MINUTES {
            report {
                "ok": False,
                "error": "expired",
                "message": "That install link expired. Try connecting again."
            };
            disengage;
        }
        if self.installation_id <= 0 {
            report {
                "ok": False,
                "error": "invalid",
                "message": "GitHub did not send an installation id."
            };
            disengage;
        }
        user_token = exchange_code(self.code);
        if not user_token {
            report {
                "ok": False,
                "error": "exchange_failed",
                "message": "GitHub would not confirm who authorized the install."
            };
            disengage;
        }
        record = user_owns_installation(user_token, self.installation_id);
        if not record {
            report {
                "ok": False,
                "error": "not_yours",
                "message": "That installation is not one your GitHub account can see."
            };
            disengage;
        }
        account = record.get("account") or {};
        login = "";
        avatar = "";
        if isinstance(account, dict) {
            login = str(account.get("login") or "");
            avatar = str(account.get("avatar_url") or "");
        }
        target.installation_id = self.installation_id;
        target.account_login = login;
        target.account_avatar = avatar;
        target.status = "ok";
        target.connected_at = now_iso();
        bind_installation(self.installation_id, jid(here));
        report {"ok": True, "connection": connection_view(target)};
    }
}


walker DisconnectGithub {
    """Forgets the installation. Imported tasks and their links stay: they
    are this workspace's own data, not GitHub's."""
    has reports: list[dict[str, any]] = [];

    # Not `drop`: jac 0.36.1's instrument_drops pass reserves `inst` and an
    # ability named drop collides with it, 422ing the endpoint (issue #123).
    can disconnect with Root entry {
        existing = [here-->[?:GithubConnection]];
        for c in existing {
            forget_installation(c.installation_id);
            unbind_installation(c.installation_id);
            del c;
        }
        report {"ok": True, "disconnected": True};
    }
}


# ---------------------------------------------------------------- reads

walker ListGithubRepos {
    """One GitHub page (100) of the repos this installation was granted,
    filtered by `query` after the fetch, so a page under a query can run
    short. `attached` marks the ones already tracked in the workspace;
    `has_more` says whether GitHub holds another page."""
    has query: str = "",
        page: int = 1,
        reports: list[dict[str, any]] = [];

    can browse with Root entry {
        c = connection_of(here);
        token = token_of(c);
        if not token {
            report not_connected();
            disengage;
        }
        page = self.page if self.page > 0 else 1;
        result = gh_request(
            token, "GET", "/installation/repositories", {"per_page": 100, "page": page}
        );
        if not result["ok"] {
            mark_invalid(c, result);
            report result;
            disengage;
        }
        data = result["data"];
        raw: list[any] = [];
        total = 0;
        if isinstance(data, dict) {
            got = data.get("repositories") or [];
            if isinstance(got, list) {
                raw = got;
            }
            total = int(data.get("total_count") or 0);
        }
        known: list[str] = [];
        for r in [here-->[?:Repo]] {
            known.append(r.full_name);
        }
        needle = self.query.strip().lower();
        rows: list[GhRepoRow] = [];
        for item in raw {
            if not isinstance(item, dict) {
                continue;
            }
            full = str(item.get("full_name") or "");
            if not full {
                continue;
            }
            if needle and needle not in full.lower() {
                continue;
            }
            rows.append(
                GhRepoRow(
                    full_name=full,
                    private=bool(item.get("private")),
                    description=str(item.get("description") or ""),
                    attached=full in known
                )
            );
        }
        rows.sort(key=lambda (r: GhRepoRow) { r.full_name; });
        report {"ok": True, "rows": rows, "page": page, "has_more": total > page * 100};
    }
}


# Shared guard for the repo-addressed reads: resolve, type-check, verify the
# repo hangs off THIS root, then verify the name is safe to interpolate into
# an api.github.com path. Returns "" when any step fails.
def owned_full_name(holder: Root, repo_id: str) -> str {
    target = resolve(repo_id);
    if not isinstance(target, Repo) or not owned(holder, target) {
        return "";
    }
    if not valid_full_name(target.full_name) {
        return "";
    }
    return target.full_name;
}


# An issue's label names, from the API's list of label objects. Shared by
# the browse rows and the import so both read labels the same way.
def label_names(item: dict[str, any]) -> list[str] {
    labels: list[str] = [];
    raw_labels = item.get("labels") or [];
    if isinstance(raw_labels, list) {
        for l in raw_labels {
            if isinstance(l, dict) {
                labels.append(str(l.get("name") or ""));
            }
        }
    }
    return labels;
}


def issue_row(
    item: dict[str, any], owned_tasks: list[Task], full_name: str
) -> GhIssueRow {
    number = int(item.get("number") or 0);
    labels = label_names(item);
    assignee = "";
    who = item.get("assignee") or {};
    if isinstance(who, dict) {
        assignee = str(who.get("login") or "");
    }
    linked = "";
    for t in owned_tasks {
        if t.gh_repo == full_name and t.gh_issue_number == number {
            linked = jid(t);
        }
    }
    return GhIssueRow(
        number=number,
        title=str(item.get("title") or ""),
        state=str(item.get("state") or ""),
        labels=labels,
        assignee=assignee,
        html_url=str(item.get("html_url") or ""),
        already_imported=bool(linked),
        imported_task_id=linked
    );
}


# People pasted PR links by hand long before any of this existed. Reading a
# number out of one lets those tasks join the sync without being re-entered,
# but only for repos the workspace actually tracks.
def pr_number_from(link: str) -> int {
    marker = "/pull/";
    if marker not in link {
        return 0;
    }
    tail = link.split(marker)[-1];
    digits = "";
    for ch in tail {
        if not ch.isdigit() {
            break;
        }
        digits = digits + ch;
    }
    if not digits {
        return 0;
    }
    return int(digits);
}


def repo_from_link(link: str) -> str {
    base = "https://github.com/";
    if not link.startswith(base) {
        return "";
    }
    parts = link[len(base):].split("/");
    if len(parts) < 2 or not parts[0] or not parts[1] {
        return "";
    }
    return parts[0] + "/" + parts[1];
}


# Sub-issue payloads name their repo as an API url; a child can live in a
# different repo than its parent, so the repo is read per child.
def repo_from_api_url(url: str) -> str {
    marker = "/repos/";
    if marker not in url {
        return "";
    }
    parts = [
        p
        for p in url.split(marker)[-1].split("/")
        if p
    ];
    if len(parts) < 2 {
        return "";
    }
    return parts[0] + "/" + parts[1];
}


# GitHub reports a merged PR as state "closed" with a merged_at timestamp,
# and a draft as state "open" with draft=true. The board wants those apart.
# A PR read off the issues stream carries merged_at under `pull_request`.
def pr_state_of(item: dict[str, any]) -> str {
    merged = item.get("merged_at");
    pr = item.get("pull_request");
    if not merged and isinstance(pr, dict) {
        merged = pr.get("merged_at");
    }
    if merged {
        return "merged";
    }
    state = str(item.get("state") or "");
    if state == "open" and bool(item.get("draft")) {
        return "draft";
    }
    return state;
}


walker ListRepoIssues {
    """One page of a repo's issues.

    A foreign repo jid reports an empty page rather than an error: it leaks
    nothing about whether the id exists, and burns no GitHub quota."""
    has repo_id: str = "",
        state: str = "open",
        page: int = 1,
        reports: list[dict[str, any]] = [];

    can browse with Root entry {
        full_name = owned_full_name(here, self.repo_id);
        if not full_name {
            report {"ok": True, "rows": [], "page": self.page, "has_more": False};
            disengage;
        }
        c = connection_of(here);
        token = token_of(c);
        if not token {
            report not_connected();
            disengage;
        }
        want = self.state if self.state in ["open", "closed", "all"] else "open";
        page = self.page if self.page > 0 else 1;
        result = gh_request(
            token,
            "GET",
            "/repos/" + full_name + "/issues",
            {"state": want, "per_page": PAGE_SIZE, "page": page}
        );
        if not result["ok"] {
            mark_invalid(c, result);
            report result;
            disengage;
        }
        data = result["data"];
        raw: list[any] = [];
        if isinstance(data, list) {
            raw = data;
        }
        owned_tasks = [here-->[?:Task]];
        rows: list[GhIssueRow] = [];
        for item in raw {
            if not isinstance(item, dict) {
                continue;
            }
            # /issues returns pull requests too; they carry this key and
            # belong on the pull-request tab, not the import table.
            if item.get("pull_request") {
                continue;
            }
            rows.append(issue_row(item, owned_tasks, full_name));
        }
        report {
            "ok": True,
            "rows": rows,
            "page": page,
            "has_more": len(raw) >= PAGE_SIZE
        };
    }
}


