"""Wipe every record under the hub (demo reset). Platform logins are kept; Accounts are rebuilt."""
def wipe() {
    h = hub();
    seen: set[str] = set();
    stack: list[any] = list([h -->]);
    doomed: list[any] = [];
    while stack {
        n = stack.pop();
        k = jid(n);
        if k in seen {
            continue;
        }
        seen.add(k);
        doomed.append(n);
        stack = stack + list([n -->]);
    }
    for n in doomed {
        del n;
    }
    h.seeded = False;
}

