"""Advance and render one frame. Returns True when the game wants to close."""
def frame -> bool {
    step = dt();
    world_t += step;
    handle_input(step);
    fire_cd -= step;
    if key_held(KEY_SPACE) and fire_cd <= 0.0 {
        fire(bullets);
