                                                {m.email}
                                            </span>
                                        }}
                                        {if m.github_username {
                                            <span
                                                key="gh"
                                                className="truncate font-mono"
                                            >
                                                @{m.github_username}
                                            </span>
                                        }}
                                        {if not m.email and not m.github_username {
                                            <span key="dash">—</span>
                                        }}
                                    </div>
                                </TableCell>
                                <TableCell className="text-right">
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={lambda { onEdit(m); }}
                                    >
                                        Edit
                                    </Button>
                                    <Button
                                        variant={"destructive"
                                            if armedId == m.id
                                            else "ghost"}
                                        size="sm"
                                        className={""
                                            if armedId == m.id
                                            else "text-destructive"}
                                        title={"Click again to archive"
                                            if armedId == m.id
                                            else "Archive"}
                                        onClick={lambda { if armedId == m.id {
                                            armedId = "";
                                            onArchive(m.id);
                                        } else {
                                            armedId = m.id;
                                        } }}
                                    >
                                        {"Confirm?" if armedId == m.id else "Archive"}
                                    </Button>
                                </TableCell>
                            </TableRow>
                        }}
                    </TableBody>
                </Table>
            </CardContent>
        </Card>;
}

