"""Reusable post composer for Little X (feed + channels)."""

import from .ui.avatar { Avatar, AvatarImage, AvatarFallback }
import from .ui.button { Button }
import from .ui.textarea { Textarea }

def:pub Composer(
    avatar: str,
    avatarAlt: str,
    placeholder: str,
    value: str,
    onChange: Callable[[str], None],
    onPost: Callable[[], None],
    rows: int = 3,
    buttonLabel: str = "Post",
    showCharRing: bool = False,
) -> JsxElement {
    charsLeft = 280 - len(value);
    ring_progress = min(1.0, (280 - charsLeft) / 280.0);
    ring_offset = str(62.83 * (1.0 - ring_progress));
    ring_color = "var(--destructive)"
        if charsLeft < 0
        else ("var(--primary)" if charsLeft < 100 else "var(--muted-foreground)");
    over_limit = showCharRing and charsLeft < 0;
    initial = avatarAlt[0].upper() if avatarAlt else "?";

    return
        <div className="flex gap-3 border-b border-border px-4 py-3">
            <Avatar className="size-10 shrink-0">
                <AvatarImage src={avatar} alt={avatarAlt}/>
                <AvatarFallback>{initial}</AvatarFallback>
            </Avatar>
            <div className="flex min-w-0 flex-1 flex-col gap-2">
                <Textarea
                    className="min-h-0 resize-none border-0 bg-transparent px-0 py-1.5 text-lg shadow-none focus-visible:ring-0 dark:bg-transparent"
                    {placeholder}
                    {value}
                    onChange={lambda (e: ChangeEvent) { onChange(e.target.value); }}
                    {rows}
                />
                <div className="flex items-center justify-end gap-3">
                    {if showCharRing and len(value) > 0 {
                        <div className="flex items-center gap-2">
                            <svg className="lx-char-ring" viewBox="0 0 24 24">
                                <circle
                                    className="lx-char-ring-bg"
                                    cx={12}
                                    cy={12}
                                    r={10}
                                />
                                <circle
                                    className="lx-char-ring-fill"
                                    cx={12}
                                    cy={12}
                                    r={10}
                                    strokeDasharray={"62.83"}
                                    strokeDashoffset={ring_offset}
                                    stroke={ring_color}
                                />
                            </svg>
                            {if charsLeft <= 20 {
                                <span
                                    className={"text-xs font-bold tabular-nums " + (
                                        "text-destructive"
                                            if charsLeft < 0
                                            else "text-primary"
                                    )}
                                >
                                    {str(charsLeft)}
                                </span>
                            }}
                        </div>
                    }}
                    <Button
                        className="rounded-full px-5 font-semibold"
                        disabled={not value.strip() or over_limit}
                        onClick={lambda { onPost(); }}
                    >
                        {buttonLabel}
                    </Button>
                </div>
            </div>
        </div>;
}

"""Chat history sidebar — ports ui/components/sidebar.tsx.

Chats are grouped by day (most-recent first) under TODAY / ISO-date micro-labels;
each row reveals a DEL action on hover. The footer MEM gauge shows resident vs
total RAM as `{used} / {ram} GB` plus an 8-cell ▮/░ bar."""

def _repeat(ch: str, n: int) -> str {
    s = "";
    i = 0;
    while i < n {
        s = s + ch;
        i = i + 1;
    }
    return s;
}

# Group consecutive chats (already sorted newest-first) by their updated_at day.
def _groups(chats: list) -> list[dict] {
    out: list[dict] = [];
    for c in chats {
        day = str(c.updated_at)[:10];
        if len(out) > 0 and out[len(out) - 1]["day"] == day {
            out[len(out) - 1]["chats"].append(c);
        } else {
            out.append({"day": day, "chats": [c]});
        }
    }
    return out;
}

# props-object component (a `def -> JsxElement` with params) — render it as JSX
# so the props object is built by the compiler and the call type-checks.
def MemGauge(used: float, total: float) -> JsxElement {
    filled = 0;
    if total > 0.0 {
        filled = int(round(used / total * 8.0));
    }
    if filled > 8 { filled = 8; }
    if filled < 0 { filled = 0; }
    return <div className="dashed-rule pt-3 font-mono text-[10px] text-muted-foreground">
        MEM {f"{used:.1f}"} / {str(int(total))} GB{" "}
        <span className="text-foreground/80">{_repeat("▮", filled)}</span>{_repeat("░", 8 - filled)}
    </div>;
}

def:pub Sidebar(
    chats: list,
    activeId: str,
    ramGb: float,
    residentGb: float,
    todayIso: str,
    busy: bool,
    onNew: Callable[([], None)],
    onOpen: Callable[([str], None)],
    onDelete: Callable[([str], None)]
) -> JsxElement {
    return <aside className="flex w-56 shrink-0 flex-col border-r border-border bg-card p-3">
        <div className="micro-label mb-3">JAC.STUDIO · fig.1</div>
        <button
            onClick={lambda (e: MouseEvent) { if not busy { onNew(); } }}
            disabled={busy}
            className="mb-3 rounded-md border border-dashed border-input py-1.5 text-xs text-foreground/80 hover:border-ring disabled:opacity-40"
        >
            + new chat
        </button>
        <div className="flex-1 overflow-y-auto">
            {if len(chats) == 0 {
                <p key="if1" className="px-2 font-mono text-[10px] text-muted-foreground/80">no chats yet</p>
                skip;
            }}
            {for grp in _groups(chats) {
                <div key={str(grp["day"])}>
                    <div className="micro-label mb-1 mt-2">{"TODAY" if grp["day"] == todayIso else str(grp["day"])}</div>
                    <div className="space-y-0.5">
                        {for c in list(grp["chats"]) {
                            <div
                                key={str(c.id)}
                                role="button"
                                tabIndex={0}
