"""Map chrome: address search, setup / loading overlays."""

import from "@hugeicons/react" { HugeiconsIcon }
import from "@hugeicons/core-free-icons" {
    Settings01Icon,
    Search01Icon,
    Cancel01Icon,
    Location01Icon
}
import from .net { with_timeout }
sv import from ..services.pulse { suggest_places, geocode_address, PlaceSuggestion }

# OpenStreetMap Nominatim etiquette: wait for a pause in typing, never a request per keystroke.
glob SUGGEST_DEBOUNCE_MS: int = 1000;
glob SUGGEST_MIN_CHARS: int = 3;

def:pub MapAddressSearch(
    dark: bool,
    onGoTo: Callable[[float, float, str], None],
    inline: bool = False,
    placeholder: str = "Search address or place…",
    fallbackHint: str = "Try again in a moment."
) -> JsxElement {
    has query: str = "",
        open: bool = False,
        busy: bool = False,
        err: str = "",
        places: list[PlaceSuggestion] = [],
        suggestSeq: int = 0,
        timerRef: Ref[any] = Ref(None);

    shell = "border-border bg-card/95 text-foreground shadow-lg backdrop-blur";
    muted = "text-muted-foreground";
    row_hover = "hover:bg-muted";

    def apply_suggestions(seq: int, rows: list[PlaceSuggestion]) {
        if seq != suggestSeq {
            return;
        }
        places = rows;
        open = len(rows) > 0;
    }

    async def fetch_suggestions(q: str) {
        ql = q.strip();
        w: any = window;
        if len(ql) < SUGGEST_MIN_CHARS or ql == w.__pulseLastSuggest {
            return;
        }
        w.__pulseLastSuggest = ql;
        suggestSeq = suggestSeq + 1;
        seq = suggestSeq;
        try {
            rows: any = await with_timeout(suggest_places(ql), None);
            if rows is None {
                w.__pulseLastSuggest = "";
                if seq == suggestSeq {
                    err = "Address search is slow right now. " + fallbackHint;
                }
                return;
            }
            apply_suggestions(seq, rows);
        } except Exception {
            w.__pulseLastSuggest = "";
            if seq == suggestSeq {
                places = [];
                open = False;
            }
        }
    }

    def schedule_suggest(q: str) {
        if timerRef.current {
            clearTimeout(timerRef.current);
        }
        timerRef.current = setTimeout(
            lambda {
                fetch_suggestions(q);
            },
            SUGGEST_DEBOUNCE_MS
        );
    }

    def on_change(e: ChangeEvent) {
        q = e.target.value;
        query = q;
        err = "";
        if len(q.strip()) < SUGGEST_MIN_CHARS {
            places = [];
            open = False;
            if timerRef.current {
                clearTimeout(timerRef.current);
                timerRef.current = None;
            }
            return;
        }
        open = len(places) > 0;
        schedule_suggest(q);
    }

    def pick_place(place: PlaceSuggestion) {
        query = place.label;
        open = False;
        err = "";
        places = [];
        onGoTo(place.lat, place.lng, place.label);
    }

    async def run_geocode {
        q = query.strip();
        if not q or busy {
            return;
        }
        busy = True;
        err = "";
        open = False;
        try {
            place: any = await with_timeout(geocode_address(q), None);
            busy = False;
            if place is None {
                err = "Address search is slow right now. " + fallbackHint;
                return;
            }
            if not place.label {
                err = "We couldn't find that address. Check the spelling. " + fallbackHint;
                return;
            }
            query = place.label;
            onGoTo(place.lat, place.lng, place.label);
        } except Exception {
            busy = False;
            err = "Address search isn't reachable right now. " + fallbackHint;
        }
    }

    def run_search {
        q = query.strip();
        if not q or busy {
            return;
        }
        if len(places) > 0 {
            pick_place(places[0]);
            return;
        }
        run_geocode();
    }

    def on_key(e: KeyboardEvent) {
        if e.key == "Enter" {
            e.preventDefault();
            run_search();
        } elif e.key == "Escape" {
            open = False;
        }
    }

    def clear_query(e: MouseEvent) {
        query = "";
        places = [];
        open = False;
        err = "";
        if timerRef.current {
            clearTimeout(timerRef.current);
            timerRef.current = None;
        }
    }

    def submit_click(e: MouseEvent) {
        run_search();
    }

    return
        <div className={
            "relative z-10 w-full"
            if inline
            else "pointer-events-auto absolute top-4 left-4 right-4 z-10 sm:right-auto sm:w-[min(100%,360px)]"
        }>
            <div
                className={
                    "flex items-center gap-2 rounded-full border pl-3 pr-1.5 py-1.5 "
                    + shell
                }
            >
                <HugeiconsIcon
                    icon={Search01Icon}
                    strokeWidth={2}
                    className={"size-4 shrink-0 " + muted}
                />
                <input
                    type="search"
