             "project": "Platform",
             "dot": "bg-chart-3",
             "who": ["Priya Raman"],
             "chip": "Backend",
             "due": "",
             "lanes": [1, 1, 1, 2]
         },
         {
             "title": "Pick the CDN region",
             "project": "Launch Site",
             "dot": "bg-chart-1",
             "who": ["Amara Perera"],
             "chip": "Infra",
             "due": "Aug 20",
